:root {
    --primary: #0d9488;
    --primary-dark: #0f766e;
    --primary-light: #14b8a6;
    --success: #059669;
    --danger: #dc2626;
    --warning: #d97706;

    --blue-50: #eff6ff;
    --blue-100: #dbeafe;
    --blue-200: #bfdbfe;
    --blue-400: #60a5fa;
    --blue-500: #3b82f6;
    --blue-600: #2563eb;
    --blue-700: #1d4ed8;
    --blue-800: #1e40af;
    --blue-900: #1e3a8a;

    --background: #ffffff; 
    --surface: #ffffff; 
    --surface-light: #f1f5f9;
    --text: #0f172a;
    --text-light: #64748b;
    --text-lighter: #94a3b8;
    --border: #e2e8f0;

    --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.05), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

body {
    font-family: 'Poppins', sans-serif;
    background-color: var(--background);
    color: var(--text);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
}

#app-container {
    display: flex;
    flex-direction: column;
    height: 100vh;
    width: 100vw;
    overflow: hidden;
}

#main-content {
    flex-grow: 1;
    overflow-y: auto;
    padding: 1rem;
    padding-bottom: 100px;
}

.app-view { display: none; }
.app-view.active { display: block; animation: fadeIn 0.3s ease; }
@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* HEADER */
.header {
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--border);
    padding: 0.75rem 1rem 0.5rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    box-shadow: var(--shadow);
}

.header-top-row { display: flex; justify-content: space-between; align-items: center; }
.header-left-col { display: flex; align-items: center; gap: 0.75rem; }
.greeting-huge { font-size: 1.25rem; font-weight: 700; display: flex; align-items: center; gap: 0.5rem; }
.couple-avatar { width: 42px; height: 42px; border-radius: 50%; border: 2px solid var(--primary); overflow: hidden; position: relative; cursor: pointer; }
.edit-overlay { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.3); display: flex; align-items: center; justify-content: center; color: white; opacity: 0; transition: opacity 0.2s; }
.couple-avatar:hover .edit-overlay { opacity: 1; }

.header-right-col { display: flex; flex-direction: column; align-items: flex-end; gap: 0.25rem; }
.date-top-right { font-size: 0.75rem; color: var(--text-light); text-transform: capitalize; }
.header-mini-actions { display: flex; align-items: center; gap: 0.5rem; }

/* Sync Indicator */
.sync-indicator {
    padding: 4px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s ease;
}
.sync-indicator.online { color: var(--success); }
.sync-indicator.syncing { color: var(--blue-600); animation: rotate 2s linear infinite; }
.sync-indicator.offline { color: var(--text-lighter); }
@keyframes rotate { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

.icon-btn { background: transparent; border: none; color: var(--text); padding: 0.25rem; border-radius: 12px; cursor: pointer; display: flex; align-items: center; justify-content: center; }
.icon-btn:hover { background: var(--surface-light); }

.header-balance-section-large { display: flex; flex-direction: column; gap: 0; }
.balance-label { font-size: 0.75rem; color: var(--text-light); font-weight: 500; }
.balance-wrapper-large { display: flex; align-items: center; gap: 0.5rem; }
.balance-value-huge { font-size: 1.75rem; font-weight: 800; color: var(--text); letter-spacing: -1px; }

.month-selector-bar { display: flex; align-items: center; justify-content: center; gap: 1rem; background: var(--surface); padding: 0.35rem; border-radius: 10px; border: 1px solid var(--border); margin-top: 0.25rem; box-shadow: var(--shadow); min-height: 40px; }
.month-display { font-size: 0.9rem; font-weight: 600; min-width: 130px; text-align: center; color: var(--primary); }
.month-btn { background: transparent; border: none; color: var(--text-light); cursor: pointer; padding: 0.2rem; display: flex; align-items: center; justify-content: center; }

/* SIDEBAR */
.sidebar-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0, 0, 0, 0.4); backdrop-filter: blur(2px); z-index: 1000; opacity: 0; visibility: hidden; transition: all 0.3s ease; }
.sidebar-overlay.active { opacity: 1; visibility: visible; }
.sidebar { position: fixed; top: 0; left: 0; width: 80%; max-width: 320px; height: 100%; background: var(--surface); z-index: 1001; transform: translateX(-100%); transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1); box-shadow: 2px 0 20px rgba(0,0,0,0.1); display: flex; flex-direction: column; }
.sidebar.active { transform: translateX(0); }
.sidebar-header { padding: 1.5rem; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between; align-items: center; }
.sidebar-content { flex-grow: 1; overflow-y: auto; padding: 1rem; padding-bottom: 100px; }

/* CARDS */
.info-cards-grid { display: grid; grid-template-columns: 1fr; gap: 0.75rem; margin-bottom: 1.5rem; }
.summary-card { background: var(--surface); padding: 0.85rem 1rem; border-radius: 16px; border: 1px solid var(--border); display: flex; flex-direction: column; box-shadow: var(--shadow); }
.card-bg-success { background-color: #d1fae5 !important; border-color: #6ee7b7 !important; }
.card-bg-danger { background-color: #fee2e2 !important; border-color: #fca5a5 !important; }
.card-bg-blue-balance { background-color: var(--blue-50) !important; border-color: var(--blue-200) !important; }
.summary-header { display: flex; justify-content: space-between; align-items: center; }
.summary-title { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700; color: var(--text-light); }
.summary-main { display: flex; align-items: baseline; gap: 0.25rem; }
.main-amount { font-size: 2rem; font-weight: 800; color: var(--text); line-height: 1.1; }
.currency-symbol { font-size: 1rem; font-weight: 600; color: var(--text-light); }
.summary-subtitle { font-size: 0.8rem; color: var(--text-light); margin-bottom: 0.35rem; font-weight: 500; }
.summary-progress-bar { height: 6px; background: rgba(0,0,0,0.05); border-radius: 3px; overflow: hidden; margin-bottom: 0.5rem; }
.summary-progress-bar-inner { height: 100%; border-radius: 3px; width: 0%; transition: width 0.5s ease; }
.summary-progress-bar-inner.income { background-color: var(--success); }
.summary-progress-bar-inner.expense { background-color: var(--danger); }
.stats-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: rgba(0,0,0,0.08); border: 1px solid rgba(0,0,0,0.08); border-radius: 10px; overflow: hidden; }
.stat-box { background: rgba(255, 255, 255, 0.6); padding: 0.4rem; display: flex; flex-direction: column; align-items: center; text-align: center; justify-content: center; gap: 2px; }
.stat-label { font-size: 0.65rem; color: var(--text-light); font-weight: 600; text-transform: uppercase; }
.stat-val { font-weight: 700; font-size: 0.9rem; }
.stat-val.success { color: var(--success); }
.stat-val.warning { color: var(--warning); }
.stat-val.danger { color: var(--danger); }

/* LISTS */
.segmented-control { display: flex; background: var(--surface-light); border-radius: 12px; padding: 0.5rem; margin-bottom: 1rem; gap: 0.5rem; border: 1px solid var(--border); overflow-x: auto; }
.segmented-btn { flex: 1; padding: 0.5rem; border: none; background: transparent; border-radius: 8px; font-size: 0.8rem; font-weight: 600; color: var(--text-light); cursor: pointer; white-space: nowrap; }
.segmented-btn.active { background: white; color: var(--primary); box-shadow: var(--shadow); }
.items-list { display: flex; flex-direction: column; gap: 0.75rem; }
.item { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 1rem; display: flex; gap: 0.75rem; cursor: pointer; box-shadow: var(--shadow); }
.item-left-col { display: flex; align-items: center; }
.switch { position: relative; display: inline-block; width: 44px; height: 24px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: #cbd5e1; transition: .4s; border-radius: 24px; }
.slider:before { position: absolute; content: ""; height: 18px; width: 18px; left: 3px; bottom: 3px; background-color: white; transition: .4s; border-radius: 50%; }
input:checked + .slider { background-color: var(--success); }
input:checked + .slider:before { transform: translateX(20px); }
.item-info-wrapper { flex: 1; display: flex; flex-direction: column; gap: 0.25rem; }
.item-primary-info { display: flex; justify-content: space-between; align-items: center; }
.item-description { font-weight: 600; font-size: 0.95rem; }
.item-description.paid { color: var(--text-lighter); text-decoration: line-through; }
.item-amount { font-weight: 700; font-size: 0.95rem; }
.item-secondary-info { display: flex; justify-content: space-between; font-size: 0.75rem; color: var(--text-light); }

/* TAB BAR */
#tab-bar { position: fixed; bottom: 0; left: 0; width: 100%; background: white; border-top: 1px solid var(--border); display: flex; justify-content: space-around; padding: 0.5rem 0 1.5rem; z-index: 100; }
.tab-btn { background: transparent; border: none; color: var(--text-lighter); display: flex; flex-direction: column; align-items: center; font-size: 0.7rem; cursor: pointer; flex: 1; }
.tab-btn.active { color: var(--primary); }

/* MODALS */
.modal { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); z-index: 2000; display: flex; align-items: flex-end; justify-content: center; visibility: hidden; opacity: 0; transition: 0.3s; }
.modal.active { visibility: visible; opacity: 1; }
.modal-content { background: white; width: 100%; max-width: 500px; border-radius: 20px 20px 0 0; padding: 1.5rem; max-height: 90vh; overflow-y: auto; transform: translateY(100%); transition: 0.3s; }
.modal.active .modal-content { transform: translateY(0); }
.modal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.5rem; }
.form-group { margin-bottom: 1rem; }
.form-label { display: block; font-size: 0.85rem; color: var(--text-light); margin-bottom: 0.4rem; font-weight: 500; }
.form-input, .form-select { 
    width: 100%; 
    padding: 0.8rem; 
    background: var(--surface-light) !important; 
    border: 1px solid var(--border) !important; 
    border-radius: 12px; 
    color: #000000 !important; /* Force black text */
    -webkit-text-fill-color: #000000 !important; /* Force black text for Safari/iOS */
}
::placeholder { color: var(--text-light); opacity: 0.7; }

.modal-footer { margin-top: 1.5rem; display: flex; gap: 1rem; justify-content: flex-end; }
.btn { background: var(--primary); color: white; border: none; padding: 0.75rem 1.25rem; border-radius: 12px; font-weight: 600; cursor: pointer; }
.btn-secondary { background: var(--surface-light); color: var(--text); }
.btn-danger { background: #fef2f2; color: var(--danger); border: 1px solid #fecaca; }

/* AI Chat */
#aiAnalysis { height: 300px; overflow-y: auto; border: 1px solid var(--border); border-radius: 12px; padding: 1rem; background: var(--surface-light); margin-bottom: 1rem; display: flex; flex-direction: column; gap: 0.75rem; }
.chat-message { max-width: 85%; }
.user-message { align-self: flex-end; }
.ai-message { align-self: flex-start; }
.message-bubble { padding: 0.75rem 1rem; border-radius: 16px; background: white; border: 1px solid var(--border); color: #000000 !important; }
.user-message .message-bubble { background: var(--primary); color: white !important; }
.ai-footer form { display: flex; gap: 0.5rem; }

