interface SummaryCardProps {
    title: string;
    value: number;
    subtitle: string;
    type: 'success' | 'danger' | 'info';
    progress?: {
        value: number;
        max: number;
    };
    stats?: {
        label1: string;
        value1: number;
        label2: string;
        value2: number;
    };
}

const SummaryCard: React.FC<SummaryCardProps> = ({ title, value, subtitle, type, progress, stats }) => {
    const format = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

    const getColors = () => {
        if (type === 'success') return { bg: 'bg-emerald-50', border: 'border-emerald-200', bar: 'bg-emerald-600', val1: 'text-emerald-600', val2: 'text-amber-600' };
        if (type === 'danger') return { bg: 'bg-red-50', border: 'border-red-200', bar: 'bg-red-600', val1: 'text-emerald-600', val2: 'text-red-600' };
        return { bg: 'bg-blue-50', border: 'border-blue-200', bar: 'bg-blue-600', val1: 'text-blue-600', val2: 'text-blue-600' };
    };

    const colors = getColors();
    const percentage = progress ? Math.min(100, (progress.value / progress.max) * 100) : 0;

    return (
        <div className={`p-4 rounded-2xl border shadow-sm flex flex-col gap-1 ${colors.bg} ${colors.border}`}>
            <div className="flex justify-between items-center">
