            {progress && (
                <div className="h-1.5 bg-black/5 rounded-full overflow-hidden mb-2">
                    <div className={`h-full rounded-full transition-all duration-500 ${colors.bar}`} style={{ width: `${percentage}%` }}></div>
                </div>
            )}

            {stats && (
                <div className="grid grid-cols-2 gap-px bg-black/5 border border-black/5 rounded-lg overflow-hidden mt-1">
