import React from 'react';
import { TrendingUp, TrendingDown, Wallet } from 'lucide-react';

interface SummaryCardProps {
    title: string;
    value: number;
    subtitle?: string;
    type: 'success' | 'danger' | 'info';
    progress?: {
        value: number;
        max: number;
    };
    compact?: boolean;
}

const SummaryCard: React.FC<SummaryCardProps> = ({ title, value, subtitle, type, progress, compact = false }) => {
    const format = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', notation: compact ? "compact" : "standard" }).format(v);

    const getStyles = () => {
        if (type === 'success') return { 
            bg: 'bg-emerald-50/50', border: 'border-emerald-100', 
            iconBg: 'bg-emerald-100', iconColor: 'text-emerald-600',
            bar: 'bg-emerald-500', text: 'text-gray-800' 
        };
        if (type === 'danger') return { 
            bg: 'bg-rose-50/50', border: 'border-rose-100', 
            iconBg: 'bg-rose-100', iconColor: 'text-rose-600',
            bar: 'bg-rose-500', text: 'text-gray-800' 
        };
        return { 
            bg: 'bg-blue-50/50', border: 'border-blue-100', 
            iconBg: 'bg-blue-100', iconColor: 'text-blue-600',
            bar: 'bg-blue-500', text: 'text-gray-800' 
        };
    };

    const s = getStyles();
    const percentage = progress ? Math.min(100, (progress.value / progress.max) * 100) : 0;

    const Icon = type === 'success' ? TrendingUp : type === 'danger' ? TrendingDown : Wallet;

    return (
        <div className={`relative overflow-hidden rounded-2xl border ${s.border} ${s.bg} ${compact ? 'p-3' : 'p-5'} transition-all duration-200 hover:shadow-sm`}>
            <div className="flex justify-between items-start mb-2">
                <div className={`p-2 rounded-xl ${s.iconBg} ${s.iconColor}`}>
                    <Icon size={compact ? 16 : 20} />
                </div>
                {compact && progress && (
                    <span className="text-[10px] font-bold px-1.5 py-0.5 bg-white/60 rounded-md text-gray-500">
                        {Math.round(percentage)}%
                    </span>
                )}
            </div>

            <div className="flex flex-col">
                <span className={`text-xs font-medium text-gray-500 uppercase tracking-wide mb-0.5`}>{title}</span>
                <span className={`${compact ? 'text-xl' : 'text-2xl'} font-bold text-gray-900 tracking-tight`}>
                    {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value)}
                </span>

                {subtitle && !compact && <span className="text-xs text-gray-400 mt-1">{subtitle}</span>}
            </div>

            {progress && (
                <div className="mt-3">
                    <div className="flex justify-between text-[10px] font-medium text-gray-500 mb-1">
                        <span>Pago: {format(progress.value)}</span>
                        {!compact && <span>Total: {format(progress.max)}</span>}
                    </div>
                    <div className="h-1.5 w-full bg-gray-200/50 rounded-full overflow-hidden">
                        <div className={`h-full rounded-full transition-all duration-500 ease-out ${s.bar}`} style={{ width: `${percentage}%` }}></div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SummaryCard;

import React from 'react';
import { Transaction } from '../types';
import { CATEGORY_ICONS } from '../constants';

interface TransactionListProps {
    transactions: Transaction[];
    onTogglePaid: (id: string, paid: boolean) => void;
    onEdit: (transaction: Transaction) => void;
    compact?: boolean;
}

const TransactionList: React.FC<TransactionListProps> = ({ transactions, onTogglePaid, onEdit, compact = false }) => {
    const format = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

    // Group transactions by date
    const grouped = transactions.reduce((groups, transaction) => {
        const date = transaction.dueDate || transaction.date || 'Sem Data';
        if (!groups[date]) {
            groups[date] = [];
        }
        groups[date].push(transaction);
        return groups;
    }, {} as Record<string, Transaction[]>);

    // Sort dates descending
    const sortedDates = Object.keys(grouped).sort((a, b) => b.localeCompare(a));

    if (transactions.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center py-12 text-gray-400">
                <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mb-3">
                    <span className="text-2xl">💤</span>
                </div>
                <p className="text-sm font-medium">Nenhuma movimentação</p>
            </div>
        );
    }

    const formatDateHeader = (dateStr: string) => {
        if (dateStr === 'Sem Data') return dateStr;
        const [year, month, day] = dateStr.split('-');
        const date = new Date(parseInt(year), parseInt(month) - 1, parseInt(day));

        const today = new Date();
        today.setHours(0,0,0,0);
        const yesterday = new Date(today);
        yesterday.setDate(yesterday.getDate() - 1);
        const transactionDate = new Date(parseInt(year), parseInt(month) - 1, parseInt(day));

        if (transactionDate.getTime() === today.getTime()) return 'Hoje';
        if (transactionDate.getTime() === yesterday.getTime()) return 'Ontem';

        return new Intl.DateTimeFormat('pt-BR', { day: 'numeric', month: 'long', weekday: 'short' }).format(date);
    };

    // Compact view just shows list without headers, sorted by date desc
    if (compact) {
        const sortedList = [...transactions].sort((a, b) => (b.dueDate || b.date || '').localeCompare(a.dueDate || a.date || '')).slice(0, 5);

        return (
            <div className="flex flex-col gap-0 divider-y divide-gray-100">
                {sortedList.map(item => (
                    <div key={item.id} className="flex items-center justify-between py-3 border-b border-gray-50 last:border-0 hover:bg-gray-50 px-2 rounded-lg transition-colors cursor-pointer" onClick={() => onEdit(item)}>
                        <div className="flex items-center gap-3 overflow-hidden">
                            <div className="w-8 h-8 rounded-full bg-gray-50 flex items-center justify-center text-sm border border-gray-100 shrink-0">
                                {CATEGORY_ICONS[item.category] || '📝'}
                            </div>
                            <div className="flex flex-col overflow-hidden">
                                <span className={`text-sm font-medium truncate ${item.paid ? 'text-gray-400 line-through' : 'text-gray-700'}`}>
                                    {item.description}
                                </span>
                                <span className="text-[10px] text-gray-400">
                                    {item.category}
                                </span>
                            </div>
                        </div>
                        <span className={`text-sm font-bold whitespace-nowrap ${item.paid ? 'text-gray-400' : 'text-gray-900'}`}>
                            {format(item.amount)}
                        </span>
                    </div>
                ))}
            </div>
        );
    }

    return (
        <div className="flex flex-col pb-20">
            {sortedDates.map(date => (
                <div key={date} className="mb-4">
                    <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-2 sticky top-0 bg-gray-50/95 backdrop-blur-sm py-2 px-1 z-10">
                        {formatDateHeader(date)}
                    </h3>
                    <div className="flex flex-col gap-2">
                        {grouped[date].map(item => (
                            <div 
                                key={item.id} 
                                className={`group bg-white rounded-2xl p-3 flex gap-3 shadow-[0_2px_8px_-4px_rgba(0,0,0,0.05)] border border-gray-100 transition-all active:scale-[0.99] cursor-pointer ${item.paid ? 'opacity-60 bg-gray-50' : 'hover:border-teal-100'}`}
                                onClick={(e) => {
                                    if (!(e.target as HTMLElement).closest('.toggle-area')) {
                                        onEdit(item);
                                    }
                                }}
                            >
                                <div className="flex items-center toggle-area">
                                     <div 
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            onTogglePaid(item.id, !item.paid);
                                        }}
                                        className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-colors ${item.paid ? 'bg-emerald-500 border-emerald-500' : 'border-gray-300 group-hover:border-teal-400'}`}
                                     >
                                        {item.paid && <span className="text-white text-xs">✓</span>}
                                     </div>
                                </div>
                                <div className="flex-1 flex flex-col gap-0.5 overflow-hidden">
                                    <div className="flex justify-between items-start">
                                        <span className={`font-semibold text-sm leading-tight truncate pr-2 ${item.paid ? 'line-through text-gray-500' : 'text-gray-800'}`}>
                                            {item.description}
                                        </span>
                                        <span className={`font-bold text-sm whitespace-nowrap ${item.paid ? 'text-gray-500' : 'text-gray-900'}`}>{format(item.amount)}</span>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <span className="text-[10px] px-1.5 py-0.5 rounded bg-gray-100 text-gray-500 font-medium flex items-center gap-1">
                                            {CATEGORY_ICONS[item.category]} {item.category}
                                        </span>
                                        {item.installments && (
                                            <span className="text-[10px] text-gray-400 font-medium">
                                                {item.installments.current}/{item.installments.total}
                                            </span>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}
        </div>
    );
};

