            </main>

            {/* Floating Action Button */}
            <button className="fixed bottom-24 right-5 w-14 h-14 bg-gray-900 text-white rounded-full shadow-[0_8px_30px_rgb(0,0,0,0.3)] flex items-center justify-center hover:scale-105 active:scale-95 transition-all z-30">
