            <nav className="fixed bottom-0 left-0 w-full bg-white/95 backdrop-blur-md border-t border-gray-100 flex justify-around py-2 pb-6 z-40 shadow-[0_-5px_20px_-5px_rgba(0,0,0,0.05)]">
                <button onClick={() => setView('home')} className={`flex flex-col items-center gap-1 p-2 rounded-xl transition-all ${view === 'home' ? 'text-teal-600 bg-teal-50' : 'text-gray-400 hover:text-gray-600'}`}>
