import { MonthData, Transaction } from '../types';
import { PAYMENT_SCHEDULE, INITIAL_GOALS, INITIAL_ACCOUNTS, MONTH_NAMES } from '../constants';

// Helper to get local data key
export const getStorageKey = (year: number, month: number) => `financeData_${year}_${month}`;

export const getMonthName = (month: number) => MONTH_NAMES[month - 1];

export const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

// Calculates which installment corresponds to the current view date
function getInstallmentInfo(startYear: number, startMonth: number, total: number, targetYear: number, targetMonth: number) {
    // Calculate difference in months
    const diff = (targetYear - startYear) * 12 + (targetMonth - startMonth);
    const current = diff + 1; // Installments start at 1

    // If current is less than 1 (starts in future) or greater than total (expired), return null
    if (current < 1 || current > total) return null;

    return { current, total };
}

// Generates data for ANY month based on configuration templates
export const generateMonthData = (year: number, month: number): MonthData => {
    // Determine reference month for salary (usually pays on prev month reference)
    let prevMonth = month - 1;
    let prevYear = year;
    if (prevMonth === 0) { prevMonth = 12; prevYear = year - 1; }

    const refMonthName = getMonthName(prevMonth);
    const salaryDay = PAYMENT_SCHEDULE[prevMonth] || `-${prevMonth.toString().padStart(2,'0')}-23`;
    const salaryDate = `${prevYear}${salaryDay}`;

    // Check if it's the initial month (Jan 2026) to mark items as paid by default
    const isJan2026 = (year === 2026 && month === 1);

    // Base Incomes (Assuming fixed salaries repeat)
    const newIncomes: Transaction[] = [
        { id: `inc_m_${year}_${month}`, description: `SALARIO MARCELLY (Ref. ${refMonthName})`, amount: 3349.92, paid: isJan2026, date: salaryDate, category: 'Salário' },
        { id: `inc_a_${year}_${month}`, description: `SALARIO ANDRE (Ref. ${refMonthName})`, amount: 3349.92, paid: isJan2026, date: salaryDate, category: 'Salário' },
        { id: `inc_mum_m_${year}_${month}`, description: 'MUMBUCA MARCELLY', amount: 650.00, paid: isJan2026, date: `${year}-${month.toString().padStart(2,'0')}-15`, category: 'Mumbuca' },
        { id: `inc_mum_a_${year}_${month}`, description: 'MUMBUCA ANDRE', amount: 650.00, paid: isJan2026, date: `${year}-${month.toString().padStart(2,'0')}-15`, category: 'Mumbuca' }
    ];

    const newExpenses: Transaction[] = [];

    // 1. RECURRING/FIXED EXPENSES (Always repeat every month)
    const cyclicalConfig = [
        { description: "ALUGUEL", amount: 1300.00, category: "Moradia", day: 1 },
        { description: "REMÉDIOS DO ANDRÉ", amount: 500.00, category: "Saúde", day: 5 },
        { description: "PSICÓLOGA DA MARCELLY", amount: 280.00, category: "Saúde", day: 10 }, 
        { description: "APPAI DA MARCELLY", amount: 110.00, category: "Saúde", day: 23 },
        { description: "FATURA DO CARTÃO DO ANDRÉ (ITAÚ)", amount: 150.00, category: "Outros", day: 24 },
        { description: "FATURA DO CARTÃO DO ANDRÉ (INTER)", amount: 150.00, category: "Outros", day: 24 },
        { description: "INTERNET DA CASA", amount: 125.00, category: "Moradia", day: 18 },
        { description: "INTERMÉDICA DO ANDRÉ", amount: 123.00, category: "Saúde", day: 15 },
        { description: "CONTA DA CLARO - ANDRÉ", amount: 55.00, category: "Moradia", day: 5 },
        { description: "CONTA DA VIVO - ANDRÉ", amount: 35.00, category: "Moradia", day: 5 },
        { description: "APPAI DO ANDRÉ", amount: 129.50, category: "Saúde", day: 20 },
        { description: "SEGURO DO CARRO", amount: 143.00, category: "Transporte", day: 20 },
        { description: "CONTA DA VIVO - MARCELLY", amount: 66.60, category: "Moradia", day: 23 }
    ];

    cyclicalConfig.forEach(c => {
        newExpenses.push({
            id: `exp_${year}_${month}_${c.description.replace(/\s/g, '')}`, // Stable ID based on month
            description: c.description,
            amount: c.amount,
            category: c.category,
            paid: false, // Future/Generated months start unpaid
            dueDate: `${year}-${month.toString().padStart(2,'0')}-${c.day.toString().padStart(2,'0')}`
        });
    });

    // 2. INSTALLMENT EXPENSES (Smart Logic)
    // sY = Start Year, sM = Start Month
    const finiteConfig = [
        { desc: "GUARDA ROUPAS", totalAmount: 914.48, cat: "Moradia", day: 10, installments: 5, sY: 2026, sM: 1 },
        { desc: "CELULAR DA MARCELLY", totalAmount: 4628.88, cat: "Outros", day: 10, installments: 12, sY: 2026, sM: 1 },
        { desc: "CONSERTO DO CARRO (OUTUBRO)", totalAmount: 1447.00, cat: "Transporte", day: 10, installments: 4, sY: 2025, sM: 11 },
        { desc: "FACULDADE DA MARCELLY", totalAmount: 2026.80, cat: "Educação", day: 12, installments: 10, sY: 2025, sM: 11 },
        { desc: "PASSAGENS AÉREAS (LILI TORRES)", totalAmount: 4038.96, cat: "Lazer", day: 15, installments: 8, sY: 2025, sM: 12 },
        { desc: "PASSAGEM AÉREA (MARCIA BRITO)", totalAmount: 1560.00, cat: "Lazer", day: 15, installments: 5, sY: 2026, sM: 2 },
        { desc: "EMPRÉSTIMO (MARCIA BISPO)", totalAmount: 2000.00, cat: "Dívidas", day: 10, installments: 10, sY: 2026, sM: 1 },
        { desc: "REEMBOLSO (REBECCA BRITO)", totalAmount: 500.00, cat: "Dívidas", day: 12, installments: 2, sY: 2026, sM: 1 },
        { desc: "PASSAGENS ONIBUS RIO X SP", totalAmount: 438.00, cat: "Transporte", day: 15, installments: 5, sY: 2026, sM: 2 },
        { desc: "MALA DO ANDRÉ", totalAmount: 179.00, cat: "Lazer", day: 15, installments: 3, sY: 2026, sM: 2 },
        { desc: "ESTADIA SÃO PAULO - IDA", totalAmount: 289.44, cat: "Lazer", day: 15, installments: 4, sY: 2026, sM: 2 },
        { desc: "ESTADIA SÃO PAULO - VOLTA", totalAmount: 358.20, cat: "Lazer", day: 15, installments: 4, sY: 2026, sM: 2 },
        { desc: "ESTADIA CIDADE DO CABO", totalAmount: 1888.25, cat: "Lazer", day: 15, installments: 5, sY: 2026, sM: 2 },
        { desc: "ESTADIA JOHANESBURGO", totalAmount: 1363.93, cat: "Lazer", day: 15, installments: 5, sY: 2026, sM: 2 },
        { desc: "RENEGOCIAR CARREFOUR", totalAmount: 5000.00, cat: "Dívidas", day: 28, installments: 16, sY: 2025, sM: 11 },
        { desc: "MULTAS", totalAmount: 1040.00, cat: "Transporte", day: 30, installments: 4, sY: 2025, sM: 10 },
        { desc: "EMPRÉSTIMO TIA CÉLIA", totalAmount: 1000.00, cat: "Dívidas", day: 10, installments: 10, sY: 2025, sM: 4 }
    ];

    finiteConfig.forEach(f => {
        // Core Logic: Does this expense exist in the requested 'year'/'month'?
        const inst = getInstallmentInfo(f.sY, f.sM, f.installments, year, month);

        // If inst is valid (current > 0 and current <= total), add it.
        if (inst) {
            const installmentAmount = f.totalAmount / f.installments;
            newExpenses.push({
                id: `fin_${f.desc.replace(/\s/g,'')}_${inst.current}`,
                description: `${f.desc} (${inst.current}/${inst.total})`,
                amount: parseFloat(installmentAmount.toFixed(2)),
                category: f.cat,
                paid: false,
                dueDate: `${year}-${month.toString().padStart(2,'0')}-${f.day.toString().padStart(2,'0')}`,
                installments: inst
            });
        }
    });

    return {
        incomes: newIncomes,
        expenses: newExpenses,
        shoppingItems: [],
        avulsosItems: [],
        goals: INITIAL_GOALS,
        bankAccounts: INITIAL_ACCOUNTS,
        updatedAt: Date.now()
    };
};

import React, { useEffect, useState, useMemo } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import SummaryCard from './components/SummaryCard';
import TransactionList from './components/TransactionList';
import AiChat from './components/AiChat';
import { MonthData, TransactionType, Transaction, FinancialProjection } from './types';
import { generateMonthData, getStorageKey } from './utils/financeUtils';
import { db, auth, isConfigured, onAuthStateChanged, signInAnonymously } from './services/firebaseConfig';
import { doc, getDoc, setDoc, onSnapshot } from 'firebase/firestore';
import { FAMILY_ID } from './constants';
import { Home, List, Target, Plus, TrendingUp, TrendingDown, ShoppingBag, User } from 'lucide-react';

const App: React.FC = () => {
    // App State
    const [currentMonth, setCurrentMonth] = useState(1);
    const [currentYear, setCurrentYear] = useState(2026);
    const [monthData, setMonthData] = useState<MonthData | null>(null);
    const [view, setView] = useState<'home' | 'transactions' | 'goals'>('home');
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [aiOpen, setAiOpen] = useState(false);
    const [syncStatus, setSyncStatus] = useState<'offline' | 'syncing' | 'online'>('offline');
    const [transactionListType, setTransactionListType] = useState<TransactionType>('expenses');

    // Load Initial Data
    useEffect(() => {
        loadData(currentYear, currentMonth);

        // Auth Setup
        if (isConfigured && auth) {
            onAuthStateChanged(auth, (user) => {
                if (user) {
                    setSyncStatus('online');
                    setupRealtimeListener(currentYear, currentMonth);
                } else {
                    signInAnonymously(auth).catch((e) => {
                        console.error("Auth Error", e);
                        setSyncStatus('offline');
                    });
                }
            });
        }
    }, []);

    const loadData = async (year: number, month: number) => {
        const key = getStorageKey(year, month);
        const local = localStorage.getItem(key);
        if (local) {
            setMonthData(JSON.parse(local));
        } else {
            const newData = generateMonthData(year, month);
            setMonthData(newData);
            saveData(newData, year, month);
        }
    };

    const saveData = async (data: MonthData, year: number, month: number) => {
        const key = getStorageKey(year, month);
        localStorage.setItem(key, JSON.stringify(data));
        setMonthData({ ...data }); // Force update

        if (syncStatus === 'online' && isConfigured) {
            setSyncStatus('syncing');
            try {
                const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
                await setDoc(docRef, data);
                setSyncStatus('online');
            } catch (e) {
                console.error("Sync failed", e);
                setSyncStatus('offline');
            }
        }
    };

    const setupRealtimeListener = (year: number, month: number) => {
        if (!isConfigured) return;
        const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
        return onSnapshot(docRef, (snap) => {
            if (snap.exists()) {
                const cloudData = snap.data() as MonthData;
                const localKey = getStorageKey(year, month);
                const localStr = localStorage.getItem(localKey);

                // Simple conflict resolution: Cloud wins if newer or local is missing
                if (!localStr || cloudData.updatedAt > JSON.parse(localStr).updatedAt) {
                    setMonthData(cloudData);
                    localStorage.setItem(localKey, JSON.stringify(cloudData));
                }
            }
        });
    };

    const handleMonthChange = (diff: number) => {
        let newMonth = currentMonth + diff;
        let newYear = currentYear;
        if (newMonth > 12) { newMonth = 1; newYear++; }
        if (newMonth < 1) { newMonth = 12; newYear--; }
        setCurrentMonth(newMonth);
        setCurrentYear(newYear);
        loadData(newYear, newMonth);
    };

    const handleTogglePaid = (id: string, paid: boolean, type: TransactionType) => {
        if (!monthData) return;
        const newData = { ...monthData };
        const item = newData[type].find(t => t.id === id);
        if (item) {
            item.paid = paid;
            item.updatedAt = Date.now(); // Internal flag not in interface but useful
            saveData(newData, currentYear, currentMonth);
        }
    };

    // --- Calculations ---
    const stats = useMemo(() => {
        if (!monthData) return { salary: { total: 0, paid: 0 }, expenses: { total: 0, paid: 0 }, mumbuca: { total: 0, paid: 0 } };

        const calc = (items: Transaction[], paidOnly = false) => 
            items.filter(i => paidOnly ? i.paid : true).reduce((sum, i) => sum + i.amount, 0);

        // Salary Logic: Category 'Salário', 'Doação', 'Renda Extra'
        const salaryItems = monthData.incomes.filter(i => ['Salário', 'Doação', 'Renda Extra'].includes(i.category));

        // Mumbuca Logic
        const mumbucaItems = monthData.incomes.filter(i => i.category === 'Mumbuca');

        return {
            salary: {
                total: calc(salaryItems),
                paid: calc(salaryItems, true)
            },
            expenses: {
                total: calc(monthData.expenses),
                paid: calc(monthData.expenses, true)
            },
            mumbuca: {
                total: calc(mumbucaItems),
                paid: calc(mumbucaItems, true),
                expenses: calc(monthData.shoppingItems),
                expensesPaid: calc(monthData.shoppingItems, true)
            }
        };
    }, [monthData]);

    // Financial Projections Logic (Simplified for brevity)
    const projections: FinancialProjection[] = useMemo(() => {
        if(!monthData) return [];
        return [{
            month: 'Atual',
            year: currentYear,
            fixedIncome: stats.salary.total,
            recurringExpenses: monthData.expenses.filter(e => !e.installments).reduce((s, e) => s + e.amount, 0),
            committedInstallments: monthData.expenses.filter(e => e.installments).reduce((s, e) => s + e.amount, 0),
            totalCommitted: stats.expenses.total,
            margin: stats.salary.total - stats.expenses.total,
            details: monthData.expenses.map(e => `${e.description}: ${e.amount}`)
        }];
    }, [monthData, stats, currentYear]);

    // Filter for Personal Debts Cards
    const personalDebts = useMemo(() => {
        if (!monthData) return [];
        const targets = ['Lili Torres', 'Marcia Brito', 'Marcia Bispo', 'Rebecca Brito'];
        return monthData.expenses.filter(e => 
            targets.some(name => e.description.toLowerCase().includes(name.toLowerCase()))
        );
    }, [monthData]);

    const getDebtColor = (name: string) => {
        const n = name.toLowerCase();
        if (n.includes('lili')) return 'from-pink-500 to-rose-600 shadow-pink-200';
        if (n.includes('marcia brito')) return 'from-violet-500 to-purple-600 shadow-violet-200';
        if (n.includes('marcia bispo')) return 'from-blue-500 to-cyan-600 shadow-blue-200';
        if (n.includes('rebecca')) return 'from-amber-400 to-orange-500 shadow-orange-200';
        return 'from-gray-500 to-gray-700';
    };

    const getPersonName = (desc: string) => {
        if (desc.toLowerCase().includes('lili')) return 'Lili Torres';
        if (desc.toLowerCase().includes('marcia brito')) return 'Marcia Brito';
        if (desc.toLowerCase().includes('marcia bispo')) return 'Marcia Bispo';
        if (desc.toLowerCase().includes('rebecca')) return 'Rebecca Brito';
        return 'Pessoa';
    }

    const balance = stats.salary.paid - stats.expenses.paid;

    if (!monthData) return <div className="flex items-center justify-center h-screen bg-gray-50"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-teal-600"></div></div>;

    // Recent transactions for dashboard (combined)
    const recentTransactions = [...monthData.expenses, ...monthData.incomes]
        .sort((a, b) => (b.date || b.dueDate || '').localeCompare(a.date || a.dueDate || ''));

    return (
        <div className="flex flex-col h-screen w-full bg-gray-50">
            <Header 
                month={currentMonth} 
                year={currentYear} 
                balance={balance}
                onMonthChange={handleMonthChange}
                onToggleSidebar={() => setSidebarOpen(true)}
                onOpenAi={() => setAiOpen(true)}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
                syncStatus={syncStatus}
            />

            <Sidebar 
                isOpen={sidebarOpen} 
                onClose={() => setSidebarOpen(false)} 
                accounts={monthData.bankAccounts}
                syncStatus={syncStatus}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
            />

            <AiChat 
                isOpen={aiOpen} 
                onClose={() => setAiOpen(false)} 
                currentMonthData={monthData}
                projections={projections}
            />

            <main className="flex-1 overflow-y-auto p-4 pb-28 scroll-smooth">
                {view === 'home' && (
                    <div className="flex flex-col gap-6 animate-fadeIn">
                        {/* Grid de Resumo */}
                        <div className="grid grid-cols-2 gap-3">
                            <SummaryCard 
                                title="Entradas"
                                value={stats.salary.total}
                                type="success"
                                progress={{ value: stats.salary.paid, max: stats.salary.total || 1 }}
                                compact={true}
                            />
                            <SummaryCard 
                                title="Despesas"
                                value={stats.expenses.total}
                                type="danger"
                                progress={{ value: stats.expenses.paid, max: stats.expenses.total || 1 }}
                                compact={true}
                            />
                        </div>

                        {/* PERSONAL DEBTS CARDS */}
                        {personalDebts.length > 0 && (
                            <div className="flex flex-col gap-2">
                                <h3 className="text-base font-extrabold text-gray-800 px-1">Compromissos Pessoais</h3>
                                <div className="grid grid-cols-2 gap-3">
                                    {personalDebts.map(debt => {
                                        const colorClass = getDebtColor(debt.description);
                                        const personName = getPersonName(debt.description);
                                        return (
                                            <div 
                                                key={debt.id} 
                                                onClick={() => handleTogglePaid(debt.id, !debt.paid, 'expenses')}
                                                className={`relative overflow-hidden rounded-2xl p-4 bg-gradient-to-br ${colorClass} text-white shadow-lg active:scale-95 transition-all cursor-pointer`}
                                            >
                                                {/* Background pattern */}
                                                <div className="absolute top-0 right-0 p-2 opacity-20">
                                                    <User size={40} />
                                                </div>

                                                <div className="flex flex-col gap-1 relative z-10">
                                                    <div className="flex justify-between items-start">
                                                        <span className="text-xs font-bold uppercase tracking-wider opacity-90">{personName}</span>
                                                        {debt.paid && <div className="bg-white/30 rounded-full p-0.5"><div className="w-1.5 h-1.5 bg-white rounded-full"></div></div>}
                                                    </div>
                                                    <span className={`text-2xl font-black tracking-tight ${debt.paid ? 'line-through opacity-70' : ''}`}>
                                                        {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(debt.amount)}
                                                    </span>
                                                    {debt.installments && (
                                                        <div className="mt-2 w-full bg-black/20 rounded-full h-1.5 overflow-hidden">
                                                            <div 
                                                                className="h-full bg-white/90 rounded-full" 
                                                                style={{ width: `${(debt.installments.current / debt.installments.total) * 100}%` }}
                                                            ></div>
                                                        </div>
                                                    )}
                                                    <span className="text-[10px] font-bold mt-1 opacity-80 truncate">
                                                        {debt.description.split('(')[0]}
                                                        {debt.installments && ` (${debt.installments.current}/${debt.installments.total})`}
                                                    </span>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        )}

                        {/* Mumbuca Card Separado */}
                        <div className="bg-white rounded-2xl p-5 shadow-sm border border-indigo-100 relative overflow-hidden">
                            <div className="absolute top-0 right-0 w-28 h-28 bg-indigo-50 rounded-bl-full -mr-8 -mt-8 opacity-50 pointer-events-none"></div>
                            <div className="flex items-center justify-between mb-4 relative z-10">
                                <div className="flex items-center gap-3">
                                    <div className="bg-indigo-100 p-2.5 rounded-xl text-indigo-600">
                                        <ShoppingBag size={22} strokeWidth={2.5} />
                                    </div>
                                    <span className="font-extrabold text-gray-700 text-lg">Saldo Mumbuca</span>
                                </div>
                                <span className="text-2xl font-black text-indigo-600">
                                    {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(stats.mumbuca.total - stats.mumbuca.expensesPaid)}
                                </span>
                            </div>
                            <div className="h-2.5 bg-gray-100 rounded-full overflow-hidden">
                                <div className="h-full bg-indigo-500 rounded-full" style={{ width: `${(stats.mumbuca.expensesPaid / (stats.mumbuca.total || 1)) * 100}%` }}></div>
                            </div>
                            <div className="flex justify-between mt-2 text-xs text-gray-500 font-bold">
                                <span>Gasto: {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(stats.mumbuca.expensesPaid)}</span>
                                <span>Total: {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(stats.mumbuca.total)}</span>
                            </div>
                        </div>

                        {/* Recent Activity Mini List */}
                        <div className="flex flex-col gap-3">
                             <div className="flex justify-between items-center px-1">
                                <h3 className="text-base font-extrabold text-gray-800">Últimas Movimentações</h3>
                                <button onClick={() => setView('transactions')} className="text-sm font-bold text-teal-600 hover:text-teal-700">Ver tudo</button>
                             </div>
                             <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-2">
                                <TransactionList 
                                    transactions={recentTransactions}
                                    onTogglePaid={() => {}} // Read only in preview
                                    onEdit={(item) => console.log("Edit", item)}
                                    compact={true}
                                />
                             </div>
                        </div>
                    </div>
                )}

                {view === 'transactions' && (
                    <div className="flex flex-col gap-4 animate-fadeIn">
                        <div className="sticky top-0 z-20 bg-gray-50 pb-2">
                            <div className="flex p-1 bg-white border border-gray-200 rounded-xl shadow-sm">
                                {(['incomes', 'expenses', 'shoppingItems', 'avulsosItems'] as const).map(type => (
                                    <button
