            </main>

            {/* Floating Action Button */}
            <button className="fixed bottom-24 right-5 w-16 h-16 bg-gray-900 text-white rounded-full shadow-[0_8px_30px_rgb(0,0,0,0.3)] flex items-center justify-center hover:scale-105 active:scale-95 transition-all z-30">
                <Plus size={32} strokeWidth={3} />
            </button>

            {/* Bottom Navigation */}
            <nav className="fixed bottom-0 left-0 w-full bg-white/95 backdrop-blur-md border-t border-gray-100 flex justify-around py-3 pb-8 z-40 shadow-[0_-5px_20px_-5px_rgba(0,0,0,0.05)]">
                <button onClick={() => setView('home')} className={`flex flex-col items-center gap-1.5 p-2 rounded-xl transition-all ${view === 'home' ? 'text-teal-600 bg-teal-50' : 'text-gray-400 hover:text-gray-600'}`}>
                    <Home size={26} strokeWidth={view === 'home' ? 3 : 2.5} />
                    <span className="text-xs font-extrabold">Início</span>
                </button>
                <button onClick={() => setView('transactions')} className={`flex flex-col items-center gap-1.5 p-2 rounded-xl transition-all ${view === 'transactions' ? 'text-teal-600 bg-teal-50' : 'text-gray-400 hover:text-gray-600'}`}>
                    <List size={26} strokeWidth={view === 'transactions' ? 3 : 2.5} />
                    <span className="text-xs font-extrabold">Extrato</span>
                </button>
                <button onClick={() => setView('goals')} className={`flex flex-col items-center gap-1.5 p-2 rounded-xl transition-all ${view === 'goals' ? 'text-teal-600 bg-teal-50' : 'text-gray-400 hover:text-gray-600'}`}>
                    <Target size={26} strokeWidth={view === 'goals' ? 3 : 2.5} />
                    <span className="text-xs font-extrabold">Metas</span>
                </button>
            </nav>
        </div>
    );
};

export default App;

