import AiChat from './components/AiChat';
import { MonthData, TransactionType, Transaction, FinancialProjection } from './types';
import { generateMonthData, getStorageKey } from './utils/financeUtils';
import { db, auth, isConfigured, onAuthStateChanged, signInAnonymously } from './services/firebaseConfig';
import { doc, getDoc, setDoc, onSnapshot } from 'firebase/firestore';
import { FAMILY_ID } from './constants';
import { Target, Plus, ShoppingBag, User, Plane } from 'lucide-react';

const App: React.FC = () => {
    // App State
    const [currentMonth, setCurrentMonth] = useState(2); // Inicia em Fevereiro
    const [currentYear, setCurrentYear] = useState(2026);
    const [monthData, setMonthData] = useState<MonthData | null>(null);
    const [view, setView] = useState<'home' | 'transactions' | 'goals'>('home');
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [aiOpen, setAiOpen] = useState(false);
    const [syncStatus, setSyncStatus] = useState<'offline' | 'syncing' | 'online'>('offline');
    const [transactionListType, setTransactionListType] = useState<TransactionType>('expenses');

    // Added state for pre-filling AI message
    const [aiInitialMessage, setAiInitialMessage] = useState<string>('');

    // Load Initial Data
    useEffect(() => {
        loadData(currentYear, currentMonth);

        // Auth Setup
        if (isConfigured && auth) {
            onAuthStateChanged(auth, (user) => {
                if (user) {
                    setSyncStatus('online');
                    setupRealtimeListener(currentYear, currentMonth);
                } else {
                    signInAnonymously(auth).catch((e) => {
                        // Handle specific API not enabled error gracefully
                        if (e.message && e.message.includes('identity-toolkit-api-has-not-been-used')) {
                            console.warn("Firebase Auth API not enabled. Running in Offline Mode.");
                        } else {
                            console.error("Auth Error", e);
                        }
                        setSyncStatus('offline');
                    });
                }
            });
        }
    }, []);

    const loadData = async (year: number, month: number) => {
        const key = getStorageKey(year, month);
        const local = localStorage.getItem(key);
        if (local) {
            setMonthData(JSON.parse(local));
        } else {
            const newData = generateMonthData(year, month);
            setMonthData(newData);
            saveData(newData, year, month);
        }
    };

    const saveData = async (data: MonthData, year: number, month: number) => {
        const key = getStorageKey(year, month);
        localStorage.setItem(key, JSON.stringify(data));
        setMonthData({ ...data }); // Force update

        if (syncStatus === 'online' && isConfigured) {
            setSyncStatus('syncing');
            try {
                const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
                await setDoc(docRef, data);
                setSyncStatus('online');
            } catch (e) {
                console.error("Sync failed", e);
                setSyncStatus('offline');
            }
        }
    };

    const setupRealtimeListener = (year: number, month: number) => {
        if (!isConfigured) return;
        const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
        return onSnapshot(docRef, (snap) => {
            if (snap.exists()) {
                const cloudData = snap.data() as MonthData;
                const localKey = getStorageKey(year, month);
                const localStr = localStorage.getItem(localKey);

                // Simple conflict resolution: Cloud wins if newer or local is missing
                if (!localStr || cloudData.updatedAt > JSON.parse(localStr).updatedAt) {
                    setMonthData(cloudData);
                    localStorage.setItem(localKey, JSON.stringify(cloudData));
                }
            }
        });
    };

    const handleMonthChange = (diff: number) => {
        let newMonth = currentMonth + diff;
        let newYear = currentYear;
        if (newMonth > 12) { newMonth = 1; newYear++; }
        if (newMonth < 1) { newMonth = 12; newYear--; }
        setCurrentMonth(newMonth);
        setCurrentYear(newYear);
        loadData(newYear, newMonth);
    };

    const handleTogglePaid = (id: string, paid: boolean, type: TransactionType) => {
        if (!monthData) return;
        const newData = { ...monthData };
        const item = newData[type].find(t => t.id === id);
        if (item) {
            item.paid = paid;
            item.updatedAt = Date.now(); // Internal flag not in interface but useful
            saveData(newData, currentYear, currentMonth);
        }
    };

    const handleToggleGroupPaid = (items: Transaction[]) => {
        if (!monthData) return;
        // Check if all are currently paid to decide whether to uncheck or check all
        const allPaid = items.every(i => i.paid);
        const newStatus = !allPaid;

        const newData = { ...monthData };
        items.forEach(groupItem => {
            const target = newData.expenses.find(e => e.id === groupItem.id);
            if (target) {
                target.paid = newStatus;
            }
        });
        newData.updatedAt = Date.now();
        saveData(newData, currentYear, currentMonth);
    };

    // Open AI with specific context
    const openAiWithContext = (message: string) => {
        setAiInitialMessage(message);
        setAiOpen(true);
    };

    // --- Calculations ---
    const stats = useMemo(() => {
        if (!monthData) return { salary: { total: 0, paid: 0 }, expenses: { total: 0, paid: 0 }, mumbuca: { total: 0, paid: 0 } };

        const calc = (items: Transaction[], paidOnly = false) => 
            items.filter(i => paidOnly ? i.paid : true).reduce((sum, i) => sum + i.amount, 0);

        // Salary Logic: Category 'Salário', 'Doação', 'Renda Extra'
        // NOTE: Does NOT include Mumbuca
        const salaryItems = monthData.incomes.filter(i => ['Salário', 'Doação', 'Renda Extra'].includes(i.category));

        // Mumbuca Logic
        const mumbucaItems = monthData.incomes.filter(i => i.category === 'Mumbuca');

        return {
            salary: {
                total: calc(salaryItems),
                paid: calc(salaryItems, true)
            },
            expenses: {
                total: calc(monthData.expenses),
                paid: calc(monthData.expenses, true)
            },
            mumbuca: {
                total: calc(mumbucaItems),
                paid: calc(mumbucaItems, true),
                expenses: calc(monthData.shoppingItems),
                expensesPaid: calc(monthData.shoppingItems, true)
            }
        };
    }, [monthData]);

    // Financial Projections Logic (Simplified for brevity)
    const projections: FinancialProjection[] = useMemo(() => {
        if(!monthData) return [];
        return [{
            month: 'Atual',
            year: currentYear,
            fixedIncome: stats.salary.total,
            recurringExpenses: monthData.expenses.filter(e => !e.installments).reduce((s, e) => s + e.amount, 0),
            committedInstallments: monthData.expenses.filter(e => e.installments).reduce((s, e) => s + e.amount, 0),
            totalCommitted: stats.expenses.total,
            margin: stats.salary.total - stats.expenses.total,
            details: monthData.expenses.map(e => `${e.description}: ${e.amount}`)
        }];
    }, [monthData, stats, currentYear]);

    // Group Personal Debts
    const groupedDebts = useMemo(() => {
        if (!monthData) return [];
        const targets = ['Lili Torres', 'Marcia Brito', 'Marcia Bispo', 'Rebecca Brito'];

        // Map to store groups
        const groups: Record<string, { 
            name: string, 
            total: number, 
            paidAmount: number, 
            items: Transaction[] 
        }> = {};

        monthData.expenses.forEach(e => {
            // Find if this expense belongs to a target person
            const personName = targets.find(t => e.description.toLowerCase().includes(t.toLowerCase()));

            if (personName) {
                if (!groups[personName]) {
                    groups[personName] = { 
                        name: personName, 
                        total: 0, 
                        paidAmount: 0, 
                        items: [] 
                    };
                }
                groups[personName].items.push(e);
                groups[personName].total += e.amount;
                if (e.paid) {
                    groups[personName].paidAmount += e.amount;
                }
            }
        });

        return Object.values(groups);
    }, [monthData]);

    const getDebtColor = (name: string) => {
        const n = name.toLowerCase();
        if (n.includes('lili')) return 'from-pink-500 to-rose-600 shadow-pink-200';
        if (n.includes('marcia brito')) return 'from-violet-500 to-purple-600 shadow-violet-200';
        if (n.includes('marcia bispo')) return 'from-blue-500 to-cyan-600 shadow-blue-200';
        if (n.includes('rebecca')) return 'from-amber-400 to-orange-500 shadow-orange-200';
        return 'from-gray-500 to-gray-700';
    };

    const balance = stats.salary.paid - stats.expenses.paid;

    if (!monthData) return <div className="flex items-center justify-center h-screen bg-gray-50"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-teal-600"></div></div>;

    return (
        <div className="flex flex-col h-screen w-full bg-gray-50">
            <Header 
                month={currentMonth} 
                year={currentYear} 
                balance={balance}
                onMonthChange={handleMonthChange}
                onToggleSidebar={() => setSidebarOpen(true)}
                onOpenAi={() => setAiOpen(true)}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
                syncStatus={syncStatus}
            />

            <Sidebar 
                isOpen={sidebarOpen} 
                onClose={() => setSidebarOpen(false)} 
                accounts={monthData.bankAccounts}
                syncStatus={syncStatus}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
                currentView={view}
                onNavigate={setView}
            />

            <AiChat 
                isOpen={aiOpen} 
                onClose={() => setAiOpen(false)} 
                currentMonthData={monthData}
                projections={projections}
                initialMessage={aiInitialMessage}
            />

            {/* Adjusted padding bottom since nav bar is gone */}
            <main className="flex-1 overflow-y-auto p-4 pb-6 scroll-smooth">
                {view === 'home' && (
                    <div className="flex flex-col gap-6 animate-fadeIn">
                        {/* Grid de Resumo */}
                        <div className="grid grid-cols-2 gap-3">
                            <SummaryCard 
                                title="Entradas"
                                value={stats.salary.total}
                                type="success"
                                progress={{ value: stats.salary.paid, max: stats.salary.total || 1 }}
                                compact={true}
                            />
                            <SummaryCard 
                                title="Despesas"
                                value={stats.expenses.total}
                                type="danger"
                                progress={{ value: stats.expenses.paid, max: stats.expenses.total || 1 }}
                                compact={true}
                            />
                        </div>

                        {/* PERSONAL DEBTS CARDS (GROUPED) */}
                        {groupedDebts.length > 0 && (
                            <div className="flex flex-col gap-2">
                                <h3 className="text-base font-extrabold text-gray-800 px-1">Compromissos Pessoais</h3>
                                <div className="grid grid-cols-2 gap-3">
                                    {groupedDebts.map(group => {
                                        const colorClass = getDebtColor(group.name);
                                        const isFullyPaid = group.paidAmount >= group.total && group.total > 0;
                                        const percentage = (group.paidAmount / (group.total || 1)) * 100;

                                        return (
                                            <div 
                                                key={group.name} 
                                                onClick={() => handleToggleGroupPaid(group.items)}
                                                className={`relative overflow-hidden rounded-2xl p-4 bg-gradient-to-br ${colorClass} text-white shadow-lg active:scale-95 transition-all cursor-pointer`}
                                            >
                                                {/* Background pattern */}
                                                <div className="absolute top-0 right-0 p-2 opacity-20">
                                                    <User size={40} />
                                                </div>

                                                <div className="flex flex-col gap-1 relative z-10">
                                                    <div className="flex justify-between items-start">
                                                        <span className="text-xs font-bold uppercase tracking-wider opacity-90">{group.name}</span>
                                                        {isFullyPaid && <div className="bg-white/30 rounded-full p-0.5"><div className="w-1.5 h-1.5 bg-white rounded-full"></div></div>}
                                                    </div>

                                                    <span className={`text-2xl font-black tracking-tight ${isFullyPaid ? 'line-through opacity-70' : ''}`}>
                                                        {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(group.total)}
                                                    </span>

                                                    {/* Progress Bar for the group */}
                                                    <div className="mt-2 w-full bg-black/20 rounded-full h-1.5 overflow-hidden flex">
                                                        <div 
                                                            className="h-full bg-white/90 rounded-full transition-all duration-500" 
                                                            style={{ width: `${percentage}%` }}
                                                        ></div>
                                                    </div>

                                                    <div className="flex justify-between items-center mt-1 opacity-80">
                                                        <span className="text-[10px] font-bold">
                                                            {group.items.length} {group.items.length === 1 ? 'item' : 'itens'}
                                                        </span>
                                                        <span className="text-[10px] font-bold">
                                                            {Math.round(percentage)}% pago
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {view === 'transactions' && (
                    <div className="flex flex-col gap-4 animate-fadeIn">
                        <div className="sticky top-0 z-20 bg-gray-50 pb-2">
                            <div className="flex p-1 bg-white border border-gray-200 rounded-xl shadow-sm">
                                {(['incomes', 'expenses', 'avulsosItems'] as const).map(type => (
                                    <button
                                        key={type}
                                        onClick={() => setTransactionListType(type)}
                                        className={`flex-1 py-3 px-2 rounded-lg text-sm font-extrabold uppercase tracking-wide transition-all ${
                                            transactionListType === type 
                                            ? 'bg-teal-50 text-teal-700' 
                                            : 'text-gray-400 hover:text-gray-600 hover:bg-gray-50'
                                        }`}
                                    >
                                        {type === 'incomes' ? 'Entradas' : 
                                         type === 'expenses' ? 'Despesas' :
                                         'Avulsos'}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <TransactionList 
                            transactions={monthData[transactionListType]}
                            onTogglePaid={(id, paid) => handleTogglePaid(id, paid, transactionListType)}
                            onEdit={(item) => console.log("Edit", item)}
                        />
                    </div>
                )}

                {view === 'goals' && (
                    <div className="flex flex-col animate-fadeIn gap-4">
                        <div className="bg-teal-600 rounded-3xl p-6 text-white shadow-lg shadow-teal-600/20">
                            <div className="flex items-center gap-3 mb-2">
                                <div className="p-2 bg-white/20 rounded-xl">
                                    <Target size={24} />
                                </div>
                                <h3 className="text-xl font-black">Metas 2026/27</h3>
                            </div>
                            <p className="text-teal-50 text-sm font-medium leading-relaxed">
                                Acompanhe seus objetivos. A inteligência artificial pode te ajudar a calcular o quanto guardar.
                            </p>
                        </div>

                        <div className="flex flex-col gap-3">
                            {monthData.goals.map(goal => (
                                <div key={goal.id} className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm flex flex-col gap-3">
                                    <div className="flex justify-between items-start">
                                        <div className="flex items-center gap-3">
                                            <div className="w-10 h-10 rounded-full bg-teal-50 flex items-center justify-center text-teal-600 font-bold">
                                                {goal.category === 'Lazer' ? '✈️' : goal.category === 'Moradia' ? '🏠' : '💰'}
                                            </div>
                                            <div className="flex flex-col">
                                                <span className="font-bold text-gray-800">{goal.name || goal.category}</span>
                                                <span className="text-xs text-gray-400 font-bold uppercase">Objetivo</span>
                                            </div>
                                        </div>
                                        {goal.id === 'goal_vacation_2027' && (
                                            <button 
                                                onClick={() => openAiWithContext('Calcule quanto devo guardar por mês para minha viagem em Janeiro de 2027, considerando minha margem livre (depois de pagar contas) e que quero usar uma parte para pagar passagens (ou parcelas) e outra para levar na viagem. Considere que em Jan/27 terei parte do salário de Dez/26.')}
                                                className="px-3 py-1.5 bg-indigo-50 text-indigo-600 text-xs font-bold rounded-lg hover:bg-indigo-100 transition-colors flex items-center gap-1"
                                            >
                                                <Plane size={14} />
                                                Planejar com IA
                                            </button>
                                        )}
                                    </div>
                                    <div className="flex justify-between items-end">
                                        <div className="flex flex-col">
                                             <span className="text-2xl font-black text-gray-900">
                                                {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', notation: 'compact' }).format(goal.amount)}
                                             </span>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </main>

            {/* Floating Action Button - Adjusted Position since Nav is gone */}
            <button className="fixed bottom-6 right-5 w-16 h-16 bg-gray-900 text-white rounded-full shadow-[0_8px_30px_rgb(0,0,0,0.3)] flex items-center justify-center hover:scale-105 active:scale-95 transition-all z-30">
                <Plus size={32} strokeWidth={3} />
            </button>
        </div>
    );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Send, X, Bot, User } from 'lucide-react';
import { getFinancialAdvice } from '../services/geminiService';
import { MonthData, FinancialProjection } from '../types';

interface AiChatProps {
    isOpen: boolean;
    onClose: () => void;
    currentMonthData: MonthData;
    projections: FinancialProjection[];
    initialMessage?: string;
}

interface Message {
    id: string;
    role: 'user' | 'ai';
    content: string;
}

const AiChat: React.FC<AiChatProps> = ({ isOpen, onClose, currentMonthData, projections, initialMessage }) => {
    const [messages, setMessages] = useState<Message[]>([
        { id: 'welcome', role: 'ai', content: 'Olá! Analisei suas finanças. **Posso calcular se aquela viagem cabe no bolso.** O que deseja saber?' }
    ]);
    const [input, setInput] = useState('');
    const [loading, setLoading] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const hasTriggeredInitial = useRef(false);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    useEffect(() => {
        if (isOpen) scrollToBottom();
    }, [messages, isOpen]);

    useEffect(() => {
        if (isOpen && initialMessage && !hasTriggeredInitial.current) {
            hasTriggeredInitial.current = true;
            triggerMessage(initialMessage);
        }
        if (!isOpen) {
            hasTriggeredInitial.current = false; // Reset for next open
        }
    }, [isOpen, initialMessage]);

    const triggerMessage = async (text: string) => {
        const userMsg: Message = { id: Date.now().toString(), role: 'user', content: text };
        setMessages(prev => [...prev, userMsg]);
        setLoading(true);

        const responseText = await getFinancialAdvice(currentMonthData, projections, text);

        const aiMsg: Message = { id: (Date.now() + 1).toString(), role: 'ai', content: responseText };
        setMessages(prev => [...prev, aiMsg]);
        setLoading(false);
    }

    const handleSend = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!input.trim() || loading) return;

        const text = input;
        setInput('');
        await triggerMessage(text);
    };

    return (
        <div className={`fixed inset-0 bg-black/50 z-50 flex items-end justify-center sm:items-center transition-opacity duration-300 ${isOpen ? 'opacity-100 visible' : 'opacity-0 invisible'}`}>
            <div 
                className={`bg-white w-full max-w-lg sm:rounded-2xl h-[85vh] sm:h-[650px] flex flex-col shadow-2xl transform transition-transform duration-300 ${isOpen ? 'translate-y-0' : 'translate-y-full sm:translate-y-10'}`}
            >
                <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-white rounded-t-2xl">
                    <div className="flex items-center gap-3">
                        <div className="p-2.5 bg-teal-50 rounded-xl text-teal-600">
                            <Bot size={24} strokeWidth={2.5} />
                        </div>
                        <h2 className="font-extrabold text-xl text-gray-900">IA Financeira</h2>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full text-gray-500">
                        <X size={24} strokeWidth={2.5} />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-5 space-y-5 bg-gray-50">
                    {messages.map(msg => (
                        <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                            <div className={`max-w-[85%] rounded-2xl p-4 shadow-sm text-base font-medium leading-relaxed ${
                                msg.role === 'user' ? 'bg-teal-600 text-white' : 'bg-white text-gray-800 border border-gray-200'
                            }`}>
                                <div dangerouslySetInnerHTML={{ 
                                    __html: msg.content.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>').replace(/\n/g, '<br>') 
                                }} />
                            </div>
                        </div>
                    ))}
                    {loading && (
                        <div className="flex justify-start">
                             <div className="bg-white text-gray-500 border border-gray-200 rounded-2xl p-4 shadow-sm text-sm flex gap-2 items-center">
                                <div className="w-2.5 h-2.5 bg-gray-400 rounded-full animate-bounce"></div>
                                <div className="w-2.5 h-2.5 bg-gray-400 rounded-full animate-bounce delay-75"></div>
                                <div className="w-2.5 h-2.5 bg-gray-400 rounded-full animate-bounce delay-150"></div>
                             </div>
                        </div>
                    )}
                    <div ref={messagesEndRef} />
                </div>

                <form onSubmit={handleSend} className="p-4 border-t border-gray-200 bg-white flex gap-3">
                    <input 
                        type="text" 
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        placeholder="Pergunte sobre suas finanças..."
                        className="flex-1 bg-gray-100 border-none rounded-xl px-5 py-4 focus:ring-2 focus:ring-teal-500 outline-none text-base font-medium text-gray-800"
                    />
                    <button 
                        type="submit" 
                        disabled={loading || !input.trim()}
                        className="p-4 bg-teal-600 text-white rounded-xl hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                    >
                        <Send size={24} strokeWidth={2.5} />
                    </button>
                </form>
            </div>
        </div>
    );
};

export default AiChat;

import React, { useEffect, useState, useMemo } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import SummaryCard from './components/SummaryCard';
import TransactionList from './components/TransactionList';
import AiChat from './components/AiChat';
import { MonthData, TransactionType, Transaction, FinancialProjection } from './types';
import { generateMonthData, getStorageKey } from './utils/financeUtils';
import { db, auth, isConfigured, onAuthStateChanged, signInAnonymously } from './services/firebaseConfig';
import { doc, getDoc, setDoc, onSnapshot } from 'firebase/firestore';
import { FAMILY_ID } from './constants';
import { Target, Plus, ShoppingBag, User, Plane } from 'lucide-react';

const App: React.FC = () => {
    // App State
    const [currentMonth, setCurrentMonth] = useState(2); // Inicia em Fevereiro
    const [currentYear, setCurrentYear] = useState(2026);
    const [monthData, setMonthData] = useState<MonthData | null>(null);
    const [view, setView] = useState<'home' | 'transactions' | 'goals'>('home');
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [aiOpen, setAiOpen] = useState(false);
    const [syncStatus, setSyncStatus] = useState<'offline' | 'syncing' | 'online'>('offline');
    const [transactionListType, setTransactionListType] = useState<TransactionType>('expenses');

    // Added state for pre-filling AI message
    const [aiInitialMessage, setAiInitialMessage] = useState<string>('');

    // Load Initial Data
    useEffect(() => {
        loadData(currentYear, currentMonth);

        // Auth Setup
        if (isConfigured && auth) {
            onAuthStateChanged(auth, (user) => {
                if (user) {
                    setSyncStatus('online');
                    setupRealtimeListener(currentYear, currentMonth);
                } else {
                    signInAnonymously(auth).catch((e) => {
                        // Handle specific API not enabled error gracefully
                        if (e.message && e.message.includes('identity-toolkit-api-has-not-been-used')) {
                            console.warn("Firebase Auth API not enabled. Running in Offline Mode.");
                        } else {
                            console.error("Auth Error", e);
                        }
                        setSyncStatus('offline');
                    });
                }
            });
        }
    }, []);

    const loadData = async (year: number, month: number) => {
        const key = getStorageKey(year, month);
        const local = localStorage.getItem(key);
        if (local) {
            setMonthData(JSON.parse(local));
        } else {
            const newData = generateMonthData(year, month);
            setMonthData(newData);
            saveData(newData, year, month);
        }
    };

    const saveData = async (data: MonthData, year: number, month: number) => {
        const key = getStorageKey(year, month);
        localStorage.setItem(key, JSON.stringify(data));
        setMonthData({ ...data }); // Force update

        if (syncStatus === 'online' && isConfigured) {
            setSyncStatus('syncing');
            try {
                const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
                await setDoc(docRef, data);
                setSyncStatus('online');
            } catch (e) {
                console.error("Sync failed", e);
                setSyncStatus('offline');
            }
        }
    };

    const setupRealtimeListener = (year: number, month: number) => {
        if (!isConfigured) return;
        const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
        return onSnapshot(docRef, (snap) => {
            if (snap.exists()) {
                const cloudData = snap.data() as MonthData;
                const localKey = getStorageKey(year, month);
                const localStr = localStorage.getItem(localKey);

                // Simple conflict resolution: Cloud wins if newer or local is missing
                if (!localStr || cloudData.updatedAt > JSON.parse(localStr).updatedAt) {
                    setMonthData(cloudData);
                    localStorage.setItem(localKey, JSON.stringify(cloudData));
                }
            }
        });
    };

    const handleMonthChange = (diff: number) => {
        let newMonth = currentMonth + diff;
        let newYear = currentYear;
        if (newMonth > 12) { newMonth = 1; newYear++; }
        if (newMonth < 1) { newMonth = 12; newYear--; }
        setCurrentMonth(newMonth);
        setCurrentYear(newYear);
        loadData(newYear, newMonth);
    };

    const handleTogglePaid = (id: string, paid: boolean, type: TransactionType) => {
        if (!monthData) return;
        const newData = { ...monthData };
        const item = newData[type].find(t => t.id === id);
        if (item) {
            item.paid = paid;
            item.updatedAt = Date.now(); // Internal flag not in interface but useful
            saveData(newData, currentYear, currentMonth);
        }
    };

    const handleToggleGroupPaid = (items: Transaction[]) => {
        if (!monthData) return;
        // Check if all are currently paid to decide whether to uncheck or check all
        const allPaid = items.every(i => i.paid);
        const newStatus = !allPaid;

        const newData = { ...monthData };
        items.forEach(groupItem => {
            const target = newData.expenses.find(e => e.id === groupItem.id);
            if (target) {
                target.paid = newStatus;
            }
        });
        newData.updatedAt = Date.now();
        saveData(newData, currentYear, currentMonth);
    };

    // Open AI with specific context
    const openAiWithContext = (message: string) => {
        setAiInitialMessage(message);
        setAiOpen(true);
    };

    // --- Calculations ---
    const stats = useMemo(() => {
        if (!monthData) return { 
            salary: { total: 0, paid: 0 }, 
            expenses: { total: 0, paid: 0 }, 
            mumbuca: { total: 0, paid: 0 },
            combined: { total: 0, paid: 0 }
        };

        const calc = (items: Transaction[], paidOnly = false) => 
            items.filter(i => paidOnly ? i.paid : true).reduce((sum, i) => sum + i.amount, 0);

        // Salary Logic: Category 'Salário', 'Doação', 'Renda Extra'
        const salaryItems = monthData.incomes.filter(i => ['Salário', 'Doação', 'Renda Extra'].includes(i.category));

        // Mumbuca Logic
        const mumbucaItems = monthData.incomes.filter(i => i.category === 'Mumbuca');

        const salaryTotal = calc(salaryItems);
        const salaryPaid = calc(salaryItems, true);

        const mumbucaTotalRaw = calc(mumbucaItems);
        const mumbucaPaidRaw = calc(mumbucaItems, true);

        // Mumbuca Net (Minus 8% fee)
        const mumbucaNetTotal = mumbucaTotalRaw * 0.92;
        const mumbucaNetPaid = mumbucaPaidRaw * 0.92;

        return {
            salary: {
                total: salaryTotal,
                paid: salaryPaid
            },
            expenses: {
                total: calc(monthData.expenses),
                paid: calc(monthData.expenses, true)
            },
            mumbuca: {
                total: mumbucaTotalRaw,
                paid: mumbucaPaidRaw,
                expenses: calc(monthData.shoppingItems),
                expensesPaid: calc(monthData.shoppingItems, true)
            },
            combined: {
                total: salaryTotal + mumbucaNetTotal,
                paid: salaryPaid + mumbucaNetPaid
            }
        };
    }, [monthData]);

    // Financial Projections Logic (Simplified for brevity)
    const projections: FinancialProjection[] = useMemo(() => {
        if(!monthData) return [];
        return [{
            month: 'Atual',
            year: currentYear,
            fixedIncome: stats.salary.total,
            recurringExpenses: monthData.expenses.filter(e => !e.installments).reduce((s, e) => s + e.amount, 0),
            committedInstallments: monthData.expenses.filter(e => e.installments).reduce((s, e) => s + e.amount, 0),
            totalCommitted: stats.expenses.total,
            margin: stats.salary.total - stats.expenses.total,
            details: monthData.expenses.map(e => `${e.description}: ${e.amount}`)
        }];
    }, [monthData, stats, currentYear]);

    // Group Personal Debts
    const groupedDebts = useMemo(() => {
        if (!monthData) return [];
        const targets = ['Lili Torres', 'Marcia Brito', 'Marcia Bispo', 'Rebecca Brito'];

        // Map to store groups
        const groups: Record<string, { 
            name: string, 
            total: number, 
            paidAmount: number, 
            items: Transaction[] 
        }> = {};

        monthData.expenses.forEach(e => {
            // Find if this expense belongs to a target person
            const personName = targets.find(t => e.description.toLowerCase().includes(t.toLowerCase()));

            if (personName) {
                if (!groups[personName]) {
                    groups[personName] = { 
                        name: personName, 
                        total: 0, 
                        paidAmount: 0, 
                        items: [] 
                    };
                }
                groups[personName].items.push(e);
                groups[personName].total += e.amount;
                if (e.paid) {
                    groups[personName].paidAmount += e.amount;
                }
            }
        });

        return Object.values(groups);
    }, [monthData]);

    const getDebtColor = (name: string) => {
        const n = name.toLowerCase();
        if (n.includes('lili')) return 'from-pink-500 to-rose-600 shadow-pink-200';
        if (n.includes('marcia brito')) return 'from-violet-500 to-purple-600 shadow-violet-200';
        if (n.includes('marcia bispo')) return 'from-blue-500 to-cyan-600 shadow-blue-200';
        if (n.includes('rebecca')) return 'from-amber-400 to-orange-500 shadow-orange-200';
        return 'from-gray-500 to-gray-700';
    };

    const balance = stats.salary.paid - stats.expenses.paid;

    if (!monthData) return <div className="flex items-center justify-center h-screen bg-gray-50"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-teal-600"></div></div>;

    return (
        <div className="flex flex-col h-screen w-full bg-gray-50">
            <Header 
                month={currentMonth} 
                year={currentYear} 
                balance={balance}
                onMonthChange={handleMonthChange}
                onToggleSidebar={() => setSidebarOpen(true)}
                onOpenAi={() => setAiOpen(true)}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
                syncStatus={syncStatus}
            />

            <Sidebar 
                isOpen={sidebarOpen} 
                onClose={() => setSidebarOpen(false)} 
                accounts={monthData.bankAccounts}
                syncStatus={syncStatus}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
                currentView={view}
                onNavigate={setView}
            />

            <AiChat 
                isOpen={aiOpen} 
                onClose={() => setAiOpen(false)} 
                currentMonthData={monthData}
                projections={projections}
                initialMessage={aiInitialMessage}
            />

            {/* Adjusted padding bottom since nav bar is gone */}
            <main className="flex-1 overflow-y-auto p-4 pb-6 scroll-smooth">
                {view === 'home' && (
                    <div className="flex flex-col gap-6 animate-fadeIn">
                        {/* Grid de Resumo */}
                        <div className="flex flex-col gap-3">
                            <div className="grid grid-cols-2 gap-3">
                                <SummaryCard 
                                    title="Entradas (Salário)"
                                    value={stats.salary.total}
                                    type="success"
                                    progress={{ value: stats.salary.paid, max: stats.salary.total || 1 }}
                                    compact={true}
                                />
                                <SummaryCard 
                                    title="Entradas (Sal. + Mumbuca)"
                                    subtitle="-8% taxa de troca"
                                    value={stats.combined.total}
                                    type="info"
                                    progress={{ value: stats.combined.paid, max: stats.combined.total || 1 }}
                                    compact={true}
                                />
                            </div>
                            <SummaryCard 
                                title="Despesas Totais"
                                value={stats.expenses.total}
                                type="danger"
                                progress={{ value: stats.expenses.paid, max: stats.expenses.total || 1 }}
                                compact={false}
                            />
                        </div>

                        {/* PERSONAL DEBTS CARDS (GROUPED) */}
                        {groupedDebts.length > 0 && (
                            <div className="flex flex-col gap-2">
                                <h3 className="text-base font-extrabold text-gray-800 px-1">Compromissos Pessoais</h3>
                                <div className="grid grid-cols-2 gap-3">
                                    {groupedDebts.map(group => {
                                        const colorClass = getDebtColor(group.name);
                                        const isFullyPaid = group.paidAmount >= group.total && group.total > 0;
                                        const percentage = (group.paidAmount / (group.total || 1)) * 100;

                                        return (
                                            <div 
                                                key={group.name} 
                                                onClick={() => handleToggleGroupPaid(group.items)}
                                                className={`relative overflow-hidden rounded-2xl p-4 bg-gradient-to-br ${colorClass} text-white shadow-lg active:scale-95 transition-all cursor-pointer`}
                                            >
                                                {/* Background pattern */}
                                                <div className="absolute top-0 right-0 p-2 opacity-20">
                                                    <User size={40} />
                                                </div>

                                                <div className="flex flex-col gap-1 relative z-10">
                                                    <div className="flex justify-between items-start">
                                                        <span className="text-xs font-bold uppercase tracking-wider opacity-90">{group.name}</span>
                                                        {isFullyPaid && <div className="bg-white/30 rounded-full p-0.5"><div className="w-1.5 h-1.5 bg-white rounded-full"></div></div>}
                                                    </div>

                                                    <span className={`text-2xl font-black tracking-tight ${isFullyPaid ? 'line-through opacity-70' : ''}`}>
                                                        {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(group.total)}
                                                    </span>

                                                    {/* Progress Bar for the group */}
                                                    <div className="mt-2 w-full bg-black/20 rounded-full h-1.5 overflow-hidden flex">
                                                        <div 
                                                            className="h-full bg-white/90 rounded-full transition-all duration-500" 
                                                            style={{ width: `${percentage}%` }}
                                                        ></div>
                                                    </div>

                                                    <div className="flex justify-between items-center mt-1 opacity-80">
                                                        <span className="text-[10px] font-bold">
                                                            {group.items.length} {group.items.length === 1 ? 'item' : 'itens'}
                                                        </span>
                                                        <span className="text-[10px] font-bold">
                                                            {Math.round(percentage)}% pago
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {view === 'transactions' && (
                    <div className="flex flex-col gap-4 animate-fadeIn">
                        <div className="sticky top-0 z-20 bg-gray-50 pb-2">
                            <div className="flex p-1 bg-white border border-gray-200 rounded-xl shadow-sm">
                                {(['incomes', 'expenses', 'avulsosItems'] as const).map(type => (
                                    <button
                                        key={type}
                                        onClick={() => setTransactionListType(type)}
                                        className={`flex-1 py-3 px-2 rounded-lg text-sm font-extrabold uppercase tracking-wide transition-all ${
                                            transactionListType === type 
                                            ? 'bg-teal-50 text-teal-700' 
                                            : 'text-gray-400 hover:text-gray-600 hover:bg-gray-50'
                                        }`}
                                    >
                                        {type === 'incomes' ? 'Entradas' : 
                                         type === 'expenses' ? 'Despesas' :
                                         'Avulsos'}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <TransactionList 
                            transactions={monthData[transactionListType]}
                            onTogglePaid={(id, paid) => handleTogglePaid(id, paid, transactionListType)}
                            onEdit={(item) => console.log("Edit", item)}
                        />
                    </div>
                )}

                {view === 'goals' && (
                    <div className="flex flex-col animate-fadeIn gap-4">
                        <div className="bg-teal-600 rounded-3xl p-6 text-white shadow-lg shadow-teal-600/20">
                            <div className="flex items-center gap-3 mb-2">
                                <div className="p-2 bg-white/20 rounded-xl">
                                    <Target size={24} />
                                </div>
                                <h3 className="text-xl font-black">Metas 2026/27</h3>
                            </div>
                            <p className="text-teal-50 text-sm font-medium leading-relaxed">
                                Acompanhe seus objetivos. A inteligência artificial pode te ajudar a calcular o quanto guardar.
                            </p>
                        </div>

                        <div className="flex flex-col gap-3">
                            {monthData.goals.map(goal => (
                                <div key={goal.id} className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm flex flex-col gap-3">
                                    <div className="flex justify-between items-start">
                                        <div className="flex items-center gap-3">
                                            <div className="w-10 h-10 rounded-full bg-teal-50 flex items-center justify-center text-teal-600 font-bold">
                                                {goal.category === 'Lazer' ? '✈️' : goal.category === 'Moradia' ? '🏠' : '💰'}
                                            </div>
                                            <div className="flex flex-col">
                                                <span className="font-bold text-gray-800">{goal.name || goal.category}</span>
                                                <span className="text-xs text-gray-400 font-bold uppercase">Objetivo</span>
                                            </div>
                                        </div>
                                        {goal.id === 'goal_vacation_2027' && (
                                            <button 
                                                onClick={() => openAiWithContext('Calcule quanto devo guardar por mês para minha viagem em Janeiro de 2027, considerando minha margem livre (depois de pagar contas) e que quero usar uma parte para pagar passagens (ou parcelas) e outra para levar na viagem. Considere que em Jan/27 terei parte do salário de Dez/26.')}
                                                className="px-3 py-1.5 bg-indigo-50 text-indigo-600 text-xs font-bold rounded-lg hover:bg-indigo-100 transition-colors flex items-center gap-1"
                                            >
                                                <Plane size={14} />
                                                Planejar com IA
                                            </button>
                                        )}
                                    </div>
                                    <div className="flex justify-between items-end">
                                        <div className="flex flex-col">
                                             <span className="text-2xl font-black text-gray-900">
                                                {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', notation: 'compact' }).format(goal.amount)}
                                             </span>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </main>

            {/* Floating Action Button - Adjusted Position since Nav is gone */}
            <button className="fixed bottom-6 right-5 w-16 h-16 bg-gray-900 text-white rounded-full shadow-[0_8px_30px_rgb(0,0,0,0.3)] flex items-center justify-center hover:scale-105 active:scale-95 transition-all z-30">
                <Plus size={32} strokeWidth={3} />
            </button>
        </div>
    );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { FinancialProjection } from '../types';
import { MonthData } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
Você é um consultor financeiro pessoal sênior, especialista em finanças domésticas.
Seu objetivo é analisar os dados financeiros fornecidos e responder às dúvidas do usuário com precisão matemática e conselhos práticos.

Regras Específicas para Viagem de Férias 2027 (Cálculo Flexível):
1. O usuário quer viajar em Janeiro de 2027.
2. NÃO sugira um valor fixo mensal se a margem do usuário variar.
3. Analise a 'margin' (sobra) de CADA mês listado na "PROJEÇÃO DE FLUXO DE CAIXA".
4. Para cada mês futuro, sugira um aporte específico baseado no que sobra naquele mês.
   - Exemplo: "Em Fevereiro sobra R$ 2.000, guarde R$ 1.000. Em Março sobra R$ 500, guarde R$ 100."
5. Lembre-se que ele precisa de dinheiro para passar o mês (Mumbuca/Alimentação), então nunca sugira guardar 100% da margem. Deixe uma gordura.
6. Some os valores sugeridos mês a mês e projete o total acumulado até Jan/2027.
7. Considere que em Jan/2027 ele terá parte do salário de Dez/2026.

Regras Gerais:
1. Analise a 'margin' (Margem Livre) de cada mês projetado.
2. Se a margem for negativa em algum mês, alerte e sugira não guardar nada naquele mês específico.
3. Seja direto, use listas e negrito para valores importantes.
4. Responda em formato de plano de ação mês a mês.
`;

export const getFinancialAdvice = async (currentMonthData: MonthData, projections: FinancialProjection[], userMessage: string): Promise<string> => {
    try {
        const prompt = `
            DADOS FINANCEIROS DO USUÁRIO:

            MÊS ATUAL:
            Entradas Totais (Salário Líquido): ${currentMonthData.incomes.filter(i => ['Salário', 'Doação', 'Renda Extra'].includes(i.category)).reduce((s,i) => s + i.amount, 0)}
            Despesas Totais: ${currentMonthData.expenses.reduce((s,i) => s + i.amount, 0)}

            PROJEÇÃO DE FLUXO DE CAIXA (PRÓXIMOS MESES COM VALORES VARIÁVEIS):
            ${JSON.stringify(projections)}

            PERGUNTA DO USUÁRIO:
            "${userMessage}"
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                systemInstruction: SYSTEM_INSTRUCTION,
            }
        });

        return response.text || "Desculpe, não consegui analisar os dados no momento.";
    } catch (error) {
        console.error("Gemini API Error:", error);
        return "Ocorreu um erro ao consultar a IA. Tente novamente mais tarde.";
    }
};

import React, { useEffect, useState, useMemo } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import SummaryCard from './components/SummaryCard';
import TransactionList from './components/TransactionList';
import AiChat from './components/AiChat';
import { MonthData, TransactionType, Transaction, FinancialProjection } from './types';
import { generateMonthData, getStorageKey } from './utils/financeUtils';
import { db, auth, isConfigured, onAuthStateChanged, signInAnonymously } from './services/firebaseConfig';
import { doc, getDoc, setDoc, onSnapshot } from 'firebase/firestore';
import { FAMILY_ID } from './constants';
import { Target, Plus, ShoppingBag, User, Plane } from 'lucide-react';

const App: React.FC = () => {
    // App State
    const [currentMonth, setCurrentMonth] = useState(2); // Inicia em Fevereiro
    const [currentYear, setCurrentYear] = useState(2026);
    const [monthData, setMonthData] = useState<MonthData | null>(null);
    const [view, setView] = useState<'home' | 'transactions' | 'goals'>('home');
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [aiOpen, setAiOpen] = useState(false);
    const [syncStatus, setSyncStatus] = useState<'offline' | 'syncing' | 'online'>('offline');
    const [transactionListType, setTransactionListType] = useState<TransactionType>('expenses');

    // Added state for pre-filling AI message
    const [aiInitialMessage, setAiInitialMessage] = useState<string>('');

    // Load Initial Data
    useEffect(() => {
        loadData(currentYear, currentMonth);

        // Auth Setup
        if (isConfigured && auth) {
            onAuthStateChanged(auth, (user) => {
                if (user) {
                    setSyncStatus('online');
                    setupRealtimeListener(currentYear, currentMonth);
                } else {
                    signInAnonymously(auth).catch((e) => {
                        // Handle specific API not enabled error gracefully
                        if (e.message && e.message.includes('identity-toolkit-api-has-not-been-used')) {
                            console.warn("Firebase Auth API not enabled. Running in Offline Mode.");
                        } else {
                            console.error("Auth Error", e);
                        }
                        setSyncStatus('offline');
                    });
                }
            });
        }
    }, []);

    const loadData = async (year: number, month: number) => {
        const key = getStorageKey(year, month);
        const local = localStorage.getItem(key);
        if (local) {
            setMonthData(JSON.parse(local));
        } else {
            const newData = generateMonthData(year, month);
            setMonthData(newData);
            saveData(newData, year, month);
        }
    };

    const saveData = async (data: MonthData, year: number, month: number) => {
        const key = getStorageKey(year, month);
        localStorage.setItem(key, JSON.stringify(data));
        setMonthData({ ...data }); // Force update

        if (syncStatus === 'online' && isConfigured) {
            setSyncStatus('syncing');
            try {
                const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
                await setDoc(docRef, data);
                setSyncStatus('online');
            } catch (e) {
                console.error("Sync failed", e);
                setSyncStatus('offline');
            }
        }
    };

    const setupRealtimeListener = (year: number, month: number) => {
        if (!isConfigured) return;
        const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
        return onSnapshot(docRef, (snap) => {
            if (snap.exists()) {
                const cloudData = snap.data() as MonthData;
                const localKey = getStorageKey(year, month);
                const localStr = localStorage.getItem(localKey);

                // Simple conflict resolution: Cloud wins if newer or local is missing
                if (!localStr || cloudData.updatedAt > JSON.parse(localStr).updatedAt) {
                    setMonthData(cloudData);
                    localStorage.setItem(localKey, JSON.stringify(cloudData));
                }
            }
        });
    };

    const handleMonthChange = (diff: number) => {
        let newMonth = currentMonth + diff;
        let newYear = currentYear;
        if (newMonth > 12) { newMonth = 1; newYear++; }
        if (newMonth < 1) { newMonth = 12; newYear--; }
        setCurrentMonth(newMonth);
        setCurrentYear(newYear);
        loadData(newYear, newMonth);
    };

    const handleTogglePaid = (id: string, paid: boolean, type: TransactionType) => {
        if (!monthData) return;
        const newData = { ...monthData };
        const item = newData[type].find(t => t.id === id);
        if (item) {
            item.paid = paid;
            item.updatedAt = Date.now(); // Internal flag not in interface but useful
            saveData(newData, currentYear, currentMonth);
        }
    };

    const handleToggleGroupPaid = (items: Transaction[]) => {
        if (!monthData) return;
        // Check if all are currently paid to decide whether to uncheck or check all
        const allPaid = items.every(i => i.paid);
        const newStatus = !allPaid;

        const newData = { ...monthData };
        items.forEach(groupItem => {
            const target = newData.expenses.find(e => e.id === groupItem.id);
            if (target) {
                target.paid = newStatus;
            }
        });
        newData.updatedAt = Date.now();
        saveData(newData, currentYear, currentMonth);
    };

    // Open AI with specific context
    const openAiWithContext = (message: string) => {
        setAiInitialMessage(message);
        setAiOpen(true);
    };

    // --- Calculations ---
    const stats = useMemo(() => {
        if (!monthData) return { 
            salary: { total: 0, paid: 0 }, 
            expenses: { total: 0, paid: 0 }, 
            mumbuca: { total: 0, paid: 0 },
            combined: { total: 0, paid: 0 }
        };

        const calc = (items: Transaction[], paidOnly = false) => 
            items.filter(i => paidOnly ? i.paid : true).reduce((sum, i) => sum + i.amount, 0);

        // Salary Logic: Category 'Salário', 'Doação', 'Renda Extra'
        const salaryItems = monthData.incomes.filter(i => ['Salário', 'Doação', 'Renda Extra'].includes(i.category));

        // Mumbuca Logic
        const mumbucaItems = monthData.incomes.filter(i => i.category === 'Mumbuca');

        const salaryTotal = calc(salaryItems);
        const salaryPaid = calc(salaryItems, true);

        const mumbucaTotalRaw = calc(mumbucaItems);
        const mumbucaPaidRaw = calc(mumbucaItems, true);

        // Mumbuca Net (Minus 8% fee)
        const mumbucaNetTotal = mumbucaTotalRaw * 0.92;
        const mumbucaNetPaid = mumbucaPaidRaw * 0.92;

        return {
            salary: {
                total: salaryTotal,
                paid: salaryPaid
            },
            expenses: {
                total: calc(monthData.expenses),
                paid: calc(monthData.expenses, true)
            },
            mumbuca: {
                total: mumbucaTotalRaw,
                paid: mumbucaPaidRaw,
                expenses: calc(monthData.shoppingItems),
                expensesPaid: calc(monthData.shoppingItems, true)
            },
            combined: {
                total: salaryTotal + mumbucaNetTotal,
                paid: salaryPaid + mumbucaNetPaid
            }
        };
    }, [monthData]);

    // Financial Projections Logic (Simplified for brevity)
    const projections: FinancialProjection[] = useMemo(() => {
        if(!monthData) return [];
        return [{
            month: 'Atual',
            year: currentYear,
            fixedIncome: stats.salary.total,
            recurringExpenses: monthData.expenses.filter(e => !e.installments).reduce((s, e) => s + e.amount, 0),
            committedInstallments: monthData.expenses.filter(e => e.installments).reduce((s, e) => s + e.amount, 0),
            totalCommitted: stats.expenses.total,
            margin: stats.salary.total - stats.expenses.total,
            details: monthData.expenses.map(e => `${e.description}: ${e.amount}`)
        }];
    }, [monthData, stats, currentYear]);

    // Group Personal Debts
    const groupedDebts = useMemo(() => {
        if (!monthData) return [];
        const targets = ['Lili Torres', 'Marcia Brito', 'Marcia Bispo', 'Rebecca Brito'];

        // Map to store groups
        const groups: Record<string, { 
            name: string, 
            total: number, 
            paidAmount: number, 
            items: Transaction[] 
        }> = {};

        monthData.expenses.forEach(e => {
            // Find if this expense belongs to a target person
            const personName = targets.find(t => e.description.toLowerCase().includes(t.toLowerCase()));

            if (personName) {
                if (!groups[personName]) {
                    groups[personName] = { 
                        name: personName, 
                        total: 0, 
                        paidAmount: 0, 
                        items: [] 
                    };
                }
                groups[personName].items.push(e);
                groups[personName].total += e.amount;
                if (e.paid) {
                    groups[personName].paidAmount += e.amount;
                }
            }
        });

        return Object.values(groups);
    }, [monthData]);

    const getDebtColor = (name: string) => {
        const n = name.toLowerCase();
        if (n.includes('lili')) return 'from-pink-500 to-rose-600 shadow-pink-200';
        if (n.includes('marcia brito')) return 'from-violet-500 to-purple-600 shadow-violet-200';
        if (n.includes('marcia bispo')) return 'from-blue-500 to-cyan-600 shadow-blue-200';
        if (n.includes('rebecca')) return 'from-amber-400 to-orange-500 shadow-orange-200';
        return 'from-gray-500 to-gray-700';
    };

    const balance = stats.salary.paid - stats.expenses.paid;

    if (!monthData) return <div className="flex items-center justify-center h-screen bg-gray-50"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-teal-600"></div></div>;

    return (
        <div className="flex flex-col h-screen w-full bg-gray-50">
            <Header 
                month={currentMonth} 
                year={currentYear} 
                balance={balance}
                onMonthChange={handleMonthChange}
                onToggleSidebar={() => setSidebarOpen(true)}
                onOpenAi={() => setAiOpen(true)}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
                syncStatus={syncStatus}
            />

            <Sidebar 
                isOpen={sidebarOpen} 
                onClose={() => setSidebarOpen(false)} 
                accounts={monthData.bankAccounts}
                syncStatus={syncStatus}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
                currentView={view}
                onNavigate={setView}
            />

            <AiChat 
                isOpen={aiOpen} 
                onClose={() => setAiOpen(false)} 
                currentMonthData={monthData}
                projections={projections}
                initialMessage={aiInitialMessage}
            />

            {/* Adjusted padding bottom since nav bar is gone */}
            <main className="flex-1 overflow-y-auto p-4 pb-6 scroll-smooth">
                {view === 'home' && (
                    <div className="flex flex-col gap-6 animate-fadeIn">
                        {/* Grid de Resumo */}
                        <div className="flex flex-col gap-3">
                            <div className="grid grid-cols-2 gap-3">
                                <SummaryCard 
                                    title="Entradas (Salário)"
                                    value={stats.salary.total}
                                    type="success"
                                    progress={{ value: stats.salary.paid, max: stats.salary.total || 1 }}
                                    compact={true}
                                />
                                <SummaryCard 
                                    title="Entradas (Sal. + Mumbuca)"
                                    subtitle="-8% taxa de troca"
                                    value={stats.combined.total}
                                    type="info"
                                    progress={{ value: stats.combined.paid, max: stats.combined.total || 1 }}
                                    compact={true}
                                />
                            </div>
                            <SummaryCard 
                                title="Despesas Totais"
                                value={stats.expenses.total}
                                type="danger"
                                progress={{ value: stats.expenses.paid, max: stats.expenses.total || 1 }}
                                compact={false}
                            />
                        </div>

                        {/* PERSONAL DEBTS CARDS (GROUPED) */}
                        {groupedDebts.length > 0 && (
                            <div className="flex flex-col gap-2">
                                <h3 className="text-base font-extrabold text-gray-800 px-1">Compromissos Pessoais</h3>
                                <div className="grid grid-cols-2 gap-3">
                                    {groupedDebts.map(group => {
                                        const colorClass = getDebtColor(group.name);
                                        const isFullyPaid = group.paidAmount >= group.total && group.total > 0;
                                        const percentage = (group.paidAmount / (group.total || 1)) * 100;

                                        return (
                                            <div 
                                                key={group.name} 
                                                onClick={() => handleToggleGroupPaid(group.items)}
                                                className={`relative overflow-hidden rounded-2xl p-4 bg-gradient-to-br ${colorClass} text-white shadow-lg active:scale-95 transition-all cursor-pointer`}
                                            >
                                                {/* Background pattern */}
