                                />
                                <SummaryCard 
                                    title="Sobras (Previsto)"
                                    value={projectedBalance}
                                    type="final"
                                    subtitle="Entradas (Azul) - Despesas"
                                    compact={true}
                                />
                            </div>
                        </div>

                        {/* PERSONAL DEBTS CARDS (GROUPED) */}
                        {groupedDebts.length > 0 && (
