        { description: "CONTA DA VIVO ANDRÉ", amount: 110.00, category: "Moradia", day: 5 }, // Valor atualizado
        { description: "SEGURO DO CARRO", amount: 143.00, category: "Transporte", day: 20 },
        { description: "CONTA DA VIVO MARCELLY", amount: 66.60, category: "Moradia", day: 23 }
    ];

    cyclicalConfig.forEach(c => {
        let finalAmount = c.amount;
        let isPaid = false;

        // Regra de Suspensão: Se for Fevereiro de 2026, pular contas da Claro e Vivo do André
        if (isFeb2026 && (c.description === "CONTA DA CLARO ANDRÉ" || c.description === "CONTA DA VIVO ANDRÉ")) {
            return; // Pula essa iteração, não adiciona a despesa
        }

        // Specific Logic for Jan 2026
        if (isJan2026) {
            if (c.description.includes("ITAÚ")) finalAmount = 56.40;
            if (paidInJan2026.some(p => c.description.toUpperCase().includes(p))) {
                isPaid = true;
            }
        }

        // Specific Logic for Feb 2026
        if (isFeb2026) {
            if (c.description.includes("ITAÚ")) finalAmount = 57.00;
        }

        newExpenses.push({
            id: `exp_${year}_${month}_${c.description.replace(/\s/g, '')}`,
            description: c.description,
            amount: finalAmount,
            category: c.category,
            paid: isPaid,
            dueDate: `${year}-${month.toString().padStart(2,'0')}-${c.day.toString().padStart(2,'0')}`,
            group: 'Despesas Fixas'
        });
    });

    // 2. INSTALLMENT EXPENSES (DESPESAS VARIÁVEIS / PARCELADAS)
    const finiteConfig = [
        { desc: "GUARDA ROUPAS (MARCIA BRITO)", totalAmount: 914.48, cat: "Moradia", day: 10, installments: 5, sY: 2026, sM: 1 },
        { desc: "CELULAR DA MARCELLY (MARCIA BISPO)", totalAmount: 4628.88, cat: "Outros", day: 10, installments: 12, sY: 2026, sM: 1 },
        { desc: "CONSERTO DO CARRO DE OUTUBRO (MARCIA BRITO)", totalAmount: 1447.00, cat: "Transporte", day: 10, installments: 4, sY: 2025, sM: 11 },
        { desc: "FACULDADE DA MARCELLY (MARCIA BRITO)", totalAmount: 2026.80, cat: "Educação", day: 12, installments: 10, sY: 2025, sM: 11 },

        // Viagem África
        { desc: "PASSAGENS AÉREAS SP X JOBURG (LILI TORRES)", totalAmount: 4038.96, cat: "Lazer", day: 15, installments: 8, sY: 2025, sM: 12 },
        { desc: "PASSAGENS AÉREAS JOBURG X CAPE TOWN (MARCIA BRITO)", totalAmount: 1560.00, cat: "Lazer", day: 15, installments: 5, sY: 2026, sM: 2 },
        { desc: "ESTADIA DE IDA EM SÃO PAULO (LILI TORRES)", totalAmount: 289.44, cat: "Lazer", day: 15, installments: 4, sY: 2026, sM: 2 },
        { desc: "ESTADIA DE VOLTA SÃO PAULO (LILI TORRES)", totalAmount: 358.20, cat: "Lazer", day: 15, installments: 4, sY: 2026, sM: 2 },
        // TOTAL ADJUSTED: 239.40 * 5 = 1197.00
        { desc: "ESTADIA EM CIDADE DO CABO (LILI TORRES)", totalAmount: 1197.00, cat: "Lazer", day: 15, installments: 5, sY: 2026, sM: 2 },
        { desc: "ESTADIA DE JOHANESBURGO (LILI TORRES)", totalAmount: 1363.93, cat: "Lazer", day: 15, installments: 5, sY: 2026, sM: 2 },

        // Outros
        { desc: "CIDADANIA PORTUGUESA (REBECCA BRITO)", totalAmount: 5040.00, cat: "Dívidas", day: 12, installments: 36, sY: 2024, sM: 11 },
        { desc: "PASSAGENS ONIBUS RIO X SP (MARCIA BRITO)", totalAmount: 438.00, cat: "Transporte", day: 15, installments: 5, sY: 2026, sM: 2 },
        { desc: "MALA DO ANDRÉ (MARCIA BRITO)", totalAmount: 179.00, cat: "Lazer", day: 15, installments: 3, sY: 2026, sM: 2 },
        { desc: "RENEGOCIAR CARREFOUR (MARCIA BRITO)", totalAmount: 5000.00, cat: "Dívidas", day: 28, installments: 16, sY: 2025, sM: 11 },
        { desc: "MULTAS", totalAmount: 1040.00, cat: "Transporte", day: 30, installments: 4, sY: 2025, sM: 10 },
        { desc: "EMPRÉSTIMO TIA CÉLIA", totalAmount: 1000.00, cat: "Dívidas", day: 10, installments: 10, sY: 2025, sM: 4 },
        { desc: "EMPRÉSTIMO CONSERTO CELULAR (MARCIA BRITO)", totalAmount: 130.00, cat: "Dívidas", day: 10, installments: 1, sY: 2026, sM: 2 },
        { desc: "DEVOLVER O EMPRÉSTIMO (MARCIA BISPO)", totalAmount: 1000.00, cat: "Dívidas", day: 10, installments: 1, sY: 2026, sM: 2 }
    ];

    finiteConfig.forEach(f => {
        const inst = getInstallmentInfo(f.sY, f.sM, f.installments, year, month);

        if (inst) {
            let isPaid = false;
            if (isJan2026) {
                if (paidInJan2026.some(p => f.desc.toUpperCase().includes(p))) {
                    isPaid = true;
                }
            }

            const installmentAmount = f.totalAmount / f.installments;
            newExpenses.push({
                id: `fin_${f.desc.replace(/\s/g,'')}_${inst.current}`,
                description: `${f.desc}`, // Nome já incluído na descrição
                amount: parseFloat(installmentAmount.toFixed(2)),
                category: f.cat,
                paid: isPaid,
                dueDate: `${year}-${month.toString().padStart(2,'0')}-${f.day.toString().padStart(2,'0')}`,
                installments: inst,
                group: 'Despesas Variáveis'
            });
        }
    });

    // --- ALGORITMO DE DISTRIBUIÇÃO DE SOBRAS (A PARTIR DE MARÇO 2026) ---
    // Calcula quanto "sobraria" antes de aplicar a distribuição, para poder fatiar essa sobra.
    if (year === 2026 && month >= 3) {
        // 1. Calcular Salários Líquidos + Mumbuca (Considerando taxa de 8% se fosse trocar, ou 100% se usar direto)
        // Para ser conservador no orçamento, vamos considerar o valor de face, 
        // mas a sobra real na "carteira" depende dos gastos.

        const totalIncome = newIncomes.reduce((acc, i) => acc + i.amount, 0);

        // Mumbuca tem "desconto" na conversão? Vamos considerar o valor nominal para distribuição
        // mas se a sobra for baseada em dinheiro vivo, Mumbuca conta.

        const totalCommitted = newExpenses.reduce((acc, e) => acc + e.amount, 0);

        // Consideramos Mumbuca com 8% de taxa para cálculo de "Sobra Real em Dinheiro"
        // (Salarios) + (Mumbuca * 0.92) - Gastos
        const salaryOnly = newIncomes.filter(i => i.category === 'Salário').reduce((acc,i) => acc + i.amount, 0);
        const mumbucaOnly = newIncomes.filter(i => i.category === 'Mumbuca').reduce((acc,i) => acc + i.amount, 0);

        // Cálculo da Sobra Projetada (Base de cálculo para distribuição)
        const projectedSurplus = (salaryOnly + (mumbucaOnly * 0.92)) - totalCommitted;

        if (projectedSurplus > 100) { // Só distribui se sobrar mais de 100 reais
            // Padrão Definido:
            // 30% Compras Casa
            // 30% Viagem (Passagens + Uso)
            // 20% Reserva Poupança
            // 20% Uso Dia a Dia

            const valCompras = projectedSurplus * 0.30;
            const valViagem = projectedSurplus * 0.30;
            const valPoupanca = projectedSurplus * 0.20;
            const valDiaDia = projectedSurplus * 0.20;

            newExpenses.push(
                {
                    id: `alloc_compras_${year}_${month}`,
                    description: '🛒 COMPRAS DO MÊS (CASA)',
                    amount: parseFloat(valCompras.toFixed(2)),
                    category: 'Alimentação',
                    paid: false,
                    date: `${year}-${month.toString().padStart(2,'0')}-05`,
                    group: 'Distribuição de Sobras (Planejamento)'
                },
                {
                    id: `alloc_viagem_${year}_${month}`,
                    description: '✈️ FUNDO VIAGEM (PASSAGEM/USO)',
                    amount: parseFloat(valViagem.toFixed(2)),
                    category: 'Lazer',
                    paid: false,
                    date: `${year}-${month.toString().padStart(2,'0')}-05`,
                    group: 'Distribuição de Sobras (Planejamento)'
                },
                {
                    id: `alloc_poupanca_${year}_${month}`,
                    description: '📈 RESERVA DE POUPANÇA',
                    amount: parseFloat(valPoupanca.toFixed(2)),
                    category: 'Investimento',
                    paid: false,
                    date: `${year}-${month.toString().padStart(2,'0')}-05`,
                    group: 'Distribuição de Sobras (Planejamento)'
                },
                {
                    id: `alloc_diadia_${year}_${month}`,
                    description: '💵 GIRO DO DIA A DIA (LIVRE)',
                    amount: parseFloat(valDiaDia.toFixed(2)),
                    category: 'Outros',
                    paid: false,
                    date: `${year}-${month.toString().padStart(2,'0')}-05`,
                    group: 'Distribuição de Sobras (Planejamento)'
                }
            );
        }
    }

    return {
        incomes: newIncomes,
        expenses: newExpenses,
        shoppingItems: [],
        avulsosItems: [],
        goals: [
            { id: "goal_vacation_2027", category: "Lazer", amount: 15000, name: "Viagem Férias 2027" },
            ...INITIAL_GOALS
        ],
        bankAccounts: INITIAL_ACCOUNTS,
        updatedAt: Date.now()
    };
};

import React from 'react';
import { Transaction } from '../types';
import { CATEGORY_ICONS } from '../constants';

interface TransactionListProps {
    transactions: Transaction[];
    onTogglePaid: (id: string, paid: boolean) => void;
    onEdit: (transaction: Transaction) => void;
    compact?: boolean;
}

const TransactionList: React.FC<TransactionListProps> = ({ transactions, onTogglePaid, onEdit, compact = false }) => {
    const format = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

    // Grouping Logic
    const grouped = transactions.reduce((groups, transaction) => {
        // If it has a group (e.g. 'Despesas Fixas'), use that. Otherwise use date.
        const key = transaction.group || transaction.dueDate || transaction.date || 'Sem Data';
        if (!groups[key]) {
            groups[key] = [];
        }
        groups[key].push(transaction);
        return groups;
    }, {} as Record<string, Transaction[]>);

    // Sorting Keys
    const sortedKeys = Object.keys(grouped).sort((a, b) => {
        // Prioritize specific groups
        const priority = [
            'Distribuição de Sobras (Planejamento)',
            'Despesas Fixas',
            'Despesas Variáveis'
        ];

        const idxA = priority.indexOf(a);
        const idxB = priority.indexOf(b);

        if (idxA !== -1 && idxB !== -1) return idxA - idxB;
        if (idxA !== -1) return -1;
        if (idxB !== -1) return 1;

        // Otherwise sort by date descending
        return b.localeCompare(a);
    });

    if (transactions.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center py-12 text-gray-400">
                <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mb-3">
                    <span className="text-3xl">💤</span>
                </div>
                <p className="text-base font-bold text-gray-500">Nenhuma movimentação</p>
            </div>
        );
    }

    const formatDateHeader = (key: string) => {
        // If it's a known group name, return as is
        if (key.includes('Distribuição') || key.includes('Despesas') || key === 'Sem Data') return key;

        // Otherwise parse as date
        const [year, month, day] = key.split('-');
        if (!year || !month || !day) return key;

        const date = new Date(parseInt(year), parseInt(month) - 1, parseInt(day));
        const today = new Date();
        today.setHours(0,0,0,0);
        const yesterday = new Date(today);
        yesterday.setDate(yesterday.getDate() - 1);
        const transactionDate = new Date(parseInt(year), parseInt(month) - 1, parseInt(day));

        if (transactionDate.getTime() === today.getTime()) return 'Hoje';
        if (transactionDate.getTime() === yesterday.getTime()) return 'Ontem';

        return new Intl.DateTimeFormat('pt-BR', { day: 'numeric', month: 'long', weekday: 'short' }).format(date);
    };

    const getHeaderColor = (key: string) => {
        if (key.includes('Distribuição')) return 'text-amber-600 bg-amber-50';
        if (key === 'Despesas Fixas') return 'text-teal-600 bg-gray-50/95';
        if (key === 'Despesas Variáveis') return 'text-indigo-600 bg-gray-50/95';
        return 'text-gray-500 bg-gray-50/95';
    };

    // Compact view logic
    if (compact) {
        const sortedList = [...transactions].sort((a, b) => (b.dueDate || b.date || '').localeCompare(a.dueDate || a.date || '')).slice(0, 5);

        return (
            <div className="flex flex-col gap-1 divider-y divide-gray-100">
                {sortedList.map(item => (
                    <div key={item.id} className="flex items-center justify-between py-3.5 border-b border-gray-50 last:border-0 hover:bg-gray-50 px-2 rounded-lg transition-colors cursor-pointer" onClick={() => onEdit(item)}>
                        <div className="flex items-center gap-3 overflow-hidden">
                            <div className="w-10 h-10 rounded-full bg-gray-50 flex items-center justify-center text-lg border border-gray-100 shrink-0">
                                {CATEGORY_ICONS[item.category] || '📝'}
                            </div>
                            <div className="flex flex-col overflow-hidden">
                                <span className={`text-base font-bold truncate ${item.paid ? 'text-gray-400 line-through' : 'text-gray-800'}`}>
                                    {item.description}
                                </span>
                                <span className="text-xs text-gray-500 font-bold">
                                    {item.category}
                                </span>
                            </div>
                        </div>
                        <span className={`text-base font-extrabold whitespace-nowrap ${item.paid ? 'text-gray-400' : 'text-gray-900'}`}>
                            {format(item.amount)}
                        </span>
                    </div>
                ))}
            </div>
        );
    }

    return (
        <div className="flex flex-col pb-20">
            {sortedKeys.map(key => (
                <div key={key} className="mb-6">
                    <h3 className={`text-sm font-extrabold uppercase tracking-wider mb-2 sticky top-0 backdrop-blur-sm py-2 px-2 rounded-lg z-10 ${getHeaderColor(key)}`}>
                        {formatDateHeader(key)}
                    </h3>
                    <div className="flex flex-col gap-2.5">
                        {grouped[key].map(item => {
                            const isAllocation = key.includes('Distribuição');
                            return (
                                <div 
                                    key={item.id} 
                                    className={`group rounded-2xl p-4 flex gap-3 shadow-[0_2px_8px_-4px_rgba(0,0,0,0.05)] border transition-all active:scale-[0.99] cursor-pointer 
                                        ${isAllocation ? 'bg-amber-50/50 border-amber-100 hover:border-amber-200' : 'bg-white border-gray-100 hover:border-teal-100'}
                                        ${item.paid ? 'opacity-60 grayscale-[0.5]' : ''}`}
                                    onClick={(e) => {
                                        if (!(e.target as HTMLElement).closest('.toggle-area')) {
                                            onEdit(item);
                                        }
                                    }}
                                >
                                    <div className="flex items-center toggle-area">
                                         <div 
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                onTogglePaid(item.id, !item.paid);
                                            }}
                                            className={`w-7 h-7 rounded-full border-2 flex items-center justify-center transition-colors 
                                                ${item.paid 
                                                    ? 'bg-emerald-500 border-emerald-500' 
                                                    : isAllocation ? 'border-amber-300 group-hover:border-amber-400' : 'border-gray-300 group-hover:border-teal-400'
                                                }`}
                                         >
                                            {item.paid && <span className="text-white text-sm font-bold">✓</span>}
                                         </div>
                                    </div>
                                    <div className="flex-1 flex flex-col gap-1 overflow-hidden">
                                        <div className="flex justify-between items-start">
                                            <span className={`font-bold text-base leading-tight truncate pr-2 ${item.paid ? 'line-through text-gray-500' : isAllocation ? 'text-amber-900' : 'text-gray-800'}`}>
                                                {item.description}
                                            </span>
                                            <span className={`font-extrabold text-base whitespace-nowrap ${item.paid ? 'text-gray-500' : isAllocation ? 'text-amber-900' : 'text-gray-900'}`}>{format(item.amount)}</span>
                                        </div>
                                        <div className="flex flex-wrap items-center gap-2 mt-1">
                                            <span className={`text-xs px-2 py-0.5 rounded font-bold flex items-center gap-1 ${isAllocation ? 'bg-amber-100 text-amber-700' : 'bg-gray-100 text-gray-600'}`}>
                                                {CATEGORY_ICONS[item.category]} {item.category}
                                            </span>

                                            {item.installments && (
                                                <span className="text-xs px-2.5 py-0.5 rounded-lg bg-violet-100 text-violet-700 font-black tracking-wide border border-violet-200 shadow-sm flex items-center gap-1">
                                                    <span className="opacity-70 font-bold text-[10px] uppercase">Parcela</span>
                                                    <span className="text-sm">{item.installments.current}/{item.installments.total}</span>
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            ))}
        </div>
    );
};

