// Calculates which installment corresponds to the current view date
function getInstallmentInfo(startYear: number, startMonth: number, total: number, targetYear: number, targetMonth: number) {
    // Calculate difference in months
    const diff = (targetYear - startYear) * 12 + (targetMonth - startMonth);
    const current = diff + 1; // Installments start at 1

    // If current is less than 1 (starts in future) or greater than total (expired), return null
    if (current < 1 || current > total) return null;

    return { current, total };
}

// Generates data for ANY month based on configuration templates
export const generateMonthData = (year: number, month: number): MonthData => {
    // Determine reference month for salary (usually pays on prev month reference)
    let prevMonth = month - 1;
    let prevYear = year;
    if (prevMonth === 0) { prevMonth = 12; prevYear = year - 1; }

    const refMonthName = getMonthName(month); // Salario é referente ao mês atual, mas recebido antes

    // Pattern: Salary day is based on the PAYMENT_SCHEDULE of the PREVIOUS month. 
    // Example: Viewing Feb (Month 2). prevMonth=1 (Jan). Schedule[1] = '-01-28'. Date = 2026-01-28.
    const salaryDaySuffix = PAYMENT_SCHEDULE[prevMonth] || '-28'; 
    const salaryDate = `${prevYear}${salaryDaySuffix}`;

    // Pattern: Mumbuca day is 15 of CURRENT month.
    const mumbucaDate = `${year}-${month.toString().padStart(2,'0')}-15`;

    // Check if it's the initial month (Jan 2026) for "Paid" logic
    const isJan2026 = (year === 2026 && month === 1);
    const isFeb2026 = (year === 2026 && month === 2);

    // Base Incomes
    const newIncomes: Transaction[] = [
        { id: `inc_m_${year}_${month}`, description: `SALARIO MARCELLY`, amount: 3436.22, paid: isJan2026, date: salaryDate, category: 'Salário' },
        { id: `inc_a_${year}_${month}`, description: `SALARIO ANDRE`, amount: 3436.22, paid: isJan2026, date: salaryDate, category: 'Salário' },
        { id: `inc_mum_m_${year}_${month}`, description: 'MUMBUCA MARCELLY', amount: 650.00, paid: isJan2026, date: mumbucaDate, category: 'Mumbuca' },
        { id: `inc_mum_a_${year}_${month}`, description: 'MUMBUCA ANDRE', amount: 650.00, paid: isJan2026, date: mumbucaDate, category: 'Mumbuca' }
    ];

    // --- 13º SALÁRIO LOGIC ---
    if (month === 7) {
        const amount13 = 1718.11; 
        newIncomes.push(
            { id: `inc_13_1_m_${year}`, description: '1ª PARCELA 13º MARCELLY', amount: amount13, paid: false, date: `${prevYear}-06-26`, category: 'Salário' },
            { id: `inc_13_1_a_${year}`, description: '1ª PARCELA 13º ANDRÉ', amount: amount13, paid: false, date: `${prevYear}-06-26`, category: 'Salário' }
        );
    }
    if (month === 1) {
        const amount13_2 = 1500.00; 
        newIncomes.push(
            { id: `inc_13_2_m_${year}`, description: '2ª PARCELA 13º MARCELLY', amount: amount13_2, paid: false, date: `${prevYear}-12-07`, category: 'Salário' },
            { id: `inc_13_2_a_${year}`, description: '2ª PARCELA 13º ANDRÉ', amount: amount13_2, paid: false, date: `${prevYear}-12-07`, category: 'Salário' }
        );
    }

    const newExpenses: Transaction[] = [];

    // List of items paid in Jan 2026
    const paidInJan2026 = ["ALUGUEL", "REMÉDIOS", "PSICÓLOGA", "APPAI", "VIVO", "CLARO", "MULTAS", "RENEGOCIAR", "PASSAGENS", "FACULDADE", "CIDADANIA", "GUARDA ROUPAS", "CELULAR", "CONSERTO", "INTERNET", "INTERMÉDICA", "FATURA"];

    // 1. RECURRING/FIXED EXPENSES
    const cyclicalConfig = [
        { description: "ALUGUEL", amount: 1300.00, category: "Moradia", day: 1 },
        { description: "PSICÓLOGA DA MARCELLY", amount: 280.00, category: "Saúde", day: 10 }, 
        { description: "APPAI DA MARCELLY (MARCIA BISPO)", amount: 110.00, category: "Saúde", day: 23 },
        { description: "APPAI DO ANDRÉ (MARCIA BRITO)", amount: 129.50, category: "Saúde", day: 20 },
        { description: "FATURA DO CARTÃO DO ANDRÉ ITAÚ", amount: 150.00, category: "Outros", day: 24 },
        { description: "INTERNET DA CASA", amount: 125.00, category: "Moradia", day: 18 },
        { description: "INTERMÉDICA DO ANDRÉ (MARCIA BRITO)", amount: 123.00, category: "Saúde", day: 15 },
        { description: "CONTA DA CLARO ANDRÉ", amount: 75.00, category: "Moradia", day: 5 },
        { description: "CONTA DA VIVO ANDRÉ", amount: 110.00, category: "Moradia", day: 5 },
        { description: "SEGURO DO CARRO", amount: 143.00, category: "Transporte", day: 20 },
        { description: "CONTA DA VIVO MARCELLY", amount: 66.60, category: "Moradia", day: 23 }
    ];

    cyclicalConfig.forEach(c => {
        let finalAmount = c.amount;
        let isPaid = false;

        if (isFeb2026 && (c.description === "CONTA DA CLARO ANDRÉ" || c.description === "CONTA DA VIVO ANDRÉ")) {
            return; 
        }

        if (isJan2026) {
            if (c.description.includes("ITAÚ")) finalAmount = 56.40;
            if (paidInJan2026.some(p => c.description.toUpperCase().includes(p))) isPaid = true;
        }
        if (isFeb2026) {
            if (c.description.includes("ITAÚ")) finalAmount = 57.00;
        }

        newExpenses.push({
            id: `exp_${year}_${month}_${c.description.replace(/\s/g, '')}`,
            description: c.description,
            amount: finalAmount,
            category: c.category,
            paid: isPaid,
            dueDate: `${year}-${month.toString().padStart(2,'0')}-${c.day.toString().padStart(2,'0')}`,
            group: 'Despesas Fixas'
        });
    });

    // 2. INSTALLMENT EXPENSES
    const finiteConfig = [
        { desc: "GUARDA ROUPAS (MARCIA BRITO)", totalAmount: 914.48, cat: "Moradia", day: 10, installments: 5, sY: 2026, sM: 1 },
        { desc: "CELULAR DA MARCELLY (MARCIA BISPO)", totalAmount: 4628.88, cat: "Outros", day: 10, installments: 12, sY: 2026, sM: 1 },
        { desc: "CONSERTO DO CARRO DE OUTUBRO (MARCIA BRITO)", totalAmount: 1447.00, cat: "Transporte", day: 10, installments: 4, sY: 2025, sM: 11 },
        { desc: "FACULDADE DA MARCELLY (MARCIA BRITO)", totalAmount: 2026.80, cat: "Educação", day: 12, installments: 10, sY: 2025, sM: 11 },
        { desc: "PASSAGENS AÉREAS SP X JOBURG (LILI TORRES)", totalAmount: 4038.96, cat: "Lazer", day: 15, installments: 8, sY: 2025, sM: 12 },
        { desc: "PASSAGENS AÉREAS JOBURG X CAPE TOWN (MARCIA BRITO)", totalAmount: 1560.00, cat: "Lazer", day: 15, installments: 5, sY: 2026, sM: 2 },
        { desc: "ESTADIA DE IDA EM SÃO PAULO (LILI TORRES)", totalAmount: 289.44, cat: "Lazer", day: 15, installments: 4, sY: 2026, sM: 2 },
        { desc: "ESTADIA DE VOLTA SÃO PAULO (LILI TORRES)", totalAmount: 358.20, cat: "Lazer", day: 15, installments: 4, sY: 2026, sM: 2 },
        { desc: "ESTADIA EM CIDADE DO CABO (LILI TORRES)", totalAmount: 1197.00, cat: "Lazer", day: 15, installments: 5, sY: 2026, sM: 2 },
        { desc: "ESTADIA DE JOHANESBURGO (LILI TORRES)", totalAmount: 1363.93, cat: "Lazer", day: 15, installments: 5, sY: 2026, sM: 2 },
        { desc: "CIDADANIA PORTUGUESA (REBECCA BRITO)", totalAmount: 5040.00, cat: "Dívidas", day: 12, installments: 36, sY: 2024, sM: 11 },
        { desc: "PASSAGENS ONIBUS RIO X SP (MARCIA BRITO)", totalAmount: 438.00, cat: "Transporte", day: 15, installments: 5, sY: 2026, sM: 2 },
        { desc: "MALA DO ANDRÉ (MARCIA BRITO)", totalAmount: 179.00, cat: "Lazer", day: 15, installments: 3, sY: 2026, sM: 2 },
        { desc: "RENEGOCIAR CARREFOUR (MARCIA BRITO)", totalAmount: 5000.00, cat: "Dívidas", day: 28, installments: 16, sY: 2025, sM: 11 },
        { desc: "MULTAS", totalAmount: 1040.00, cat: "Transporte", day: 30, installments: 4, sY: 2025, sM: 10 },
        { desc: "EMPRÉSTIMO TIA CÉLIA", totalAmount: 1000.00, cat: "Dívidas", day: 10, installments: 10, sY: 2025, sM: 4 },
        { desc: "EMPRÉSTIMO CONSERTO CELULAR (MARCIA BRITO)", totalAmount: 130.00, cat: "Dívidas", day: 10, installments: 1, sY: 2026, sM: 2 },
        { desc: "DEVOLVER O EMPRÉSTIMO (MARCIA BISPO)", totalAmount: 1000.00, cat: "Dívidas", day: 10, installments: 1, sY: 2026, sM: 2 }
    ];

    finiteConfig.forEach(f => {
        const inst = getInstallmentInfo(f.sY, f.sM, f.installments, year, month);
        if (inst) {
            let isPaid = false;
            if (isJan2026) {
                if (paidInJan2026.some(p => f.desc.toUpperCase().includes(p))) isPaid = true;
            }
            const installmentAmount = f.totalAmount / f.installments;
            newExpenses.push({
                id: `fin_${f.desc.replace(/\s/g,'')}_${inst.current}`,
                description: `${f.desc}`, 
                amount: parseFloat(installmentAmount.toFixed(2)),
                category: f.cat,
                paid: isPaid,
                dueDate: `${year}-${month.toString().padStart(2,'0')}-${f.day.toString().padStart(2,'0')}`,
                installments: inst,
                group: 'Despesas Variáveis'
            });
        }
    });

    const newGoals: Goal[] = [];

    // --- ALGORITMO DE DISTRIBUIÇÃO DE SOBRAS (A PARTIR DE MARÇO 2026) ---
    if (year === 2026 && month >= 3) {
        const salaryOnly = newIncomes.filter(i => i.category === 'Salário').reduce((acc,i) => acc + i.amount, 0);
        const mumbucaOnly = newIncomes.filter(i => i.category === 'Mumbuca').reduce((acc,i) => acc + i.amount, 0);
        const totalCommitted = newExpenses.reduce((acc, e) => acc + e.amount, 0);

        const projectedSurplus = (salaryOnly + (mumbucaOnly * 0.92)) - totalCommitted;

        if (projectedSurplus > 100) {
            const valCompras = projectedSurplus * 0.30;
            const valViagem = projectedSurplus * 0.30;
            const valPoupanca = projectedSurplus * 0.20;
            const valDiaDia = projectedSurplus * 0.20;

            const allocations = [
                { id: `alloc_compras_${year}_${month}`, desc: '🛒 COMPRAS DO MÊS (CASA)', amt: valCompras, cat: 'Alimentação' },
                { id: `alloc_viagem_${year}_${month}`, desc: '✈️ FUNDO VIAGEM (PASSAGEM/USO)', amt: valViagem, cat: 'Lazer' },
                { id: `alloc_poupanca_${year}_${month}`, desc: '📈 RESERVA DE POUPANÇA', amt: valPoupanca, cat: 'Investimento' },
                { id: `alloc_diadia_${year}_${month}`, desc: '💵 GIRO DO DIA A DIA (LIVRE)', amt: valDiaDia, cat: 'Outros' }
            ];

            allocations.forEach(alloc => {
                // Add Expense Transaction
                newExpenses.push({
                    id: alloc.id,
                    description: alloc.desc,
                    amount: parseFloat(alloc.amt.toFixed(2)),
                    category: alloc.cat,
                    paid: false,
                    date: `${year}-${month.toString().padStart(2,'0')}-05`,
                    group: 'Distribuição de Sobras (Planejamento)',
                    isDistribution: true // Flag to identify and exclude from Sobras calculation
                });

                // Add corresponding Goal
                newGoals.push({
                    id: `goal_${alloc.id}`,
                    name: alloc.desc,
                    amount: parseFloat(alloc.amt.toFixed(2)),
                    category: alloc.cat,
                    linkedTransactionId: alloc.id
                });
            });
        }
    }

    return {
        incomes: newIncomes,
        expenses: newExpenses,
        shoppingItems: [],
        avulsosItems: [],
        goals: newGoals, // Use the dynamically generated goals
        bankAccounts: INITIAL_ACCOUNTS,
        updatedAt: Date.now()
    };
};

import React, { useEffect, useState, useMemo } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import SummaryCard from './components/SummaryCard';
import TransactionList from './components/TransactionList';
import AiChat from './components/AiChat';
import { MonthData, TransactionType, Transaction, FinancialProjection } from './types';
import { generateMonthData, getStorageKey } from './utils/financeUtils';
import { db, auth, isConfigured, onAuthStateChanged, signInAnonymously } from './services/firebaseConfig';
import { doc, getDoc, setDoc, onSnapshot } from 'firebase/firestore';
import { FAMILY_ID } from './constants';
import { Target, Plus, ShoppingBag, User, Plane, Wallet, PiggyBank, Home as HomeIcon } from 'lucide-react';

const App: React.FC = () => {
    // App State
    const [currentMonth, setCurrentMonth] = useState(2); // Inicia em Fevereiro
    const [currentYear, setCurrentYear] = useState(2026);
    const [monthData, setMonthData] = useState<MonthData | null>(null);
    const [view, setView] = useState<'home' | 'transactions' | 'goals'>('home');
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [aiOpen, setAiOpen] = useState(false);
    const [syncStatus, setSyncStatus] = useState<'offline' | 'syncing' | 'online'>('offline');
    const [transactionListType, setTransactionListType] = useState<TransactionType>('expenses');

    // Added state for pre-filling AI message
    const [aiInitialMessage, setAiInitialMessage] = useState<string>('');

    // Load Initial Data
    useEffect(() => {
        loadData(currentYear, currentMonth);

        // Auth Setup
        if (isConfigured && auth) {
            onAuthStateChanged(auth, (user) => {
                if (user) {
                    setSyncStatus('online');
                    setupRealtimeListener(currentYear, currentMonth);
                } else {
                    signInAnonymously(auth).catch((e) => {
                        // Handle specific API not enabled error gracefully
                        if (e.message && e.message.includes('identity-toolkit-api-has-not-been-used')) {
                            console.warn("Firebase Auth API not enabled. Running in Offline Mode.");
                        } else {
                            console.error("Auth Error", e);
                        }
                        setSyncStatus('offline');
                    });
                }
            });
        }
    }, []);

    const loadData = async (year: number, month: number) => {
        const key = getStorageKey(year, month);
        const local = localStorage.getItem(key);
        if (local) {
            setMonthData(JSON.parse(local));
        } else {
            const newData = generateMonthData(year, month);
            setMonthData(newData);
            saveData(newData, year, month);
        }
    };

    const saveData = async (data: MonthData, year: number, month: number) => {
        const key = getStorageKey(year, month);
        localStorage.setItem(key, JSON.stringify(data));
        setMonthData({ ...data }); // Force update

        if (syncStatus === 'online' && isConfigured) {
            setSyncStatus('syncing');
            try {
                const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
                await setDoc(docRef, data);
                setSyncStatus('online');
            } catch (e) {
                console.error("Sync failed", e);
                setSyncStatus('offline');
            }
        }
    };

    const setupRealtimeListener = (year: number, month: number) => {
        if (!isConfigured) return;
        const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
        return onSnapshot(docRef, (snap) => {
            if (snap.exists()) {
                const cloudData = snap.data() as MonthData;
                const localKey = getStorageKey(year, month);
                const localStr = localStorage.getItem(localKey);

                // Simple conflict resolution: Cloud wins if newer or local is missing
                if (!localStr || cloudData.updatedAt > JSON.parse(localStr).updatedAt) {
                    setMonthData(cloudData);
                    localStorage.setItem(localKey, JSON.stringify(cloudData));
                }
            }
        });
    };

    const handleMonthChange = (diff: number) => {
        let newMonth = currentMonth + diff;
        let newYear = currentYear;
        if (newMonth > 12) { newMonth = 1; newYear++; }
        if (newMonth < 1) { newMonth = 12; newYear--; }
        setCurrentMonth(newMonth);
        setCurrentYear(newYear);
        loadData(newYear, newMonth);
    };

    const handleTogglePaid = (id: string, paid: boolean, type: TransactionType) => {
        if (!monthData) return;
        const newData = { ...monthData };
        const item = newData[type].find(t => t.id === id);
        if (item) {
            item.paid = paid;
            item.updatedAt = Date.now(); // Internal flag not in interface but useful
            saveData(newData, currentYear, currentMonth);
        }
    };

    const handleToggleGroupPaid = (items: Transaction[]) => {
        if (!monthData) return;
        // Check if all are currently paid to decide whether to uncheck or check all
        const allPaid = items.every(i => i.paid);
        const newStatus = !allPaid;

        const newData = { ...monthData };
        items.forEach(groupItem => {
            const target = newData.expenses.find(e => e.id === groupItem.id);
            if (target) {
                target.paid = newStatus;
            }
        });
        newData.updatedAt = Date.now();
        saveData(newData, currentYear, currentMonth);
    };

    // Open AI with specific context
    const openAiWithContext = (message: string) => {
        setAiInitialMessage(message);
        setAiOpen(true);
    };

    // --- Calculations ---
    const stats = useMemo(() => {
        if (!monthData) return { 
            salary: { total: 0, paid: 0 }, 
            expenses: { total: 0, paid: 0 }, 
            mumbuca: { total: 0, paid: 0 },
            combined: { total: 0, paid: 0 },
            surplusRaw: 0
        };

        const calc = (items: Transaction[], paidOnly = false) => 
            items.filter(i => paidOnly ? i.paid : true).reduce((sum, i) => sum + i.amount, 0);

        // Salary Logic: Category 'Salário', 'Doação', 'Renda Extra'
        const salaryItems = monthData.incomes.filter(i => ['Salário', 'Doação', 'Renda Extra'].includes(i.category));

        // Mumbuca Logic
        const mumbucaItems = monthData.incomes.filter(i => i.category === 'Mumbuca');

        const salaryTotal = calc(salaryItems);
        const salaryPaid = calc(salaryItems, true);

        const mumbucaTotalRaw = calc(mumbucaItems);
        const mumbucaPaidRaw = calc(mumbucaItems, true);

        // Mumbuca Net (Minus 8% fee)
        const mumbucaNetTotal = mumbucaTotalRaw * 0.92;
        const mumbucaNetPaid = mumbucaPaidRaw * 0.92;

        const combinedTotal = salaryTotal + mumbucaNetTotal;
        const expensesTotal = calc(monthData.expenses);

        // Calculate surplus WITHOUT distribution items (to show the "Available to Distribute" amount)
        const expensesWithoutDistribution = monthData.expenses
            .filter(e => !e.isDistribution)
            .reduce((sum, i) => sum + i.amount, 0);

        return {
            salary: {
                total: salaryTotal,
                paid: salaryPaid
            },
            expenses: {
                total: expensesTotal,
                paid: calc(monthData.expenses, true)
            },
            mumbuca: {
                total: mumbucaTotalRaw,
                paid: mumbucaPaidRaw,
                expenses: calc(monthData.shoppingItems),
                expensesPaid: calc(monthData.shoppingItems, true)
            },
            combined: {
                total: combinedTotal,
                paid: salaryPaid + mumbucaNetPaid
            },
            surplusRaw: combinedTotal - expensesWithoutDistribution
        };
    }, [monthData]);

    // Financial Projections Logic (Simplified for brevity)
    const projections: FinancialProjection[] = useMemo(() => {
        if(!monthData) return [];
        return [{
            month: 'Atual',
            year: currentYear,
            fixedIncome: stats.salary.total,
            recurringExpenses: monthData.expenses.filter(e => !e.installments).reduce((s, e) => s + e.amount, 0),
            committedInstallments: monthData.expenses.filter(e => e.installments).reduce((s, e) => s + e.amount, 0),
            totalCommitted: stats.expenses.total,
            margin: stats.salary.total - stats.expenses.total,
            details: monthData.expenses.map(e => `${e.description}: ${e.amount}`)
        }];
    }, [monthData, stats, currentYear]);

    // Group Personal Debts
    const groupedDebts = useMemo(() => {
        if (!monthData) return [];
        const targets = ['Lili Torres', 'Marcia Brito', 'Marcia Bispo', 'Rebecca Brito'];

        // Map to store groups
        const groups: Record<string, { 
            name: string, 
            total: number, 
            paidAmount: number, 
            items: Transaction[] 
        }> = {};

        monthData.expenses.forEach(e => {
            // Find if this expense belongs to a target person
            const personName = targets.find(t => e.description.toLowerCase().includes(t.toLowerCase()));

            if (personName) {
                if (!groups[personName]) {
                    groups[personName] = { 
                        name: personName, 
                        total: 0, 
                        paidAmount: 0, 
                        items: [] 
                    };
                }
                groups[personName].items.push(e);
                groups[personName].total += e.amount;
                if (e.paid) {
                    groups[personName].paidAmount += e.amount;
                }
            }
        });

        return Object.values(groups);
    }, [monthData]);

    const getDebtColor = (name: string) => {
        const n = name.toLowerCase();
        if (n.includes('lili')) return 'from-pink-500 to-rose-600 shadow-pink-200';
        if (n.includes('marcia brito')) return 'from-violet-500 to-purple-600 shadow-violet-200';
        if (n.includes('marcia bispo')) return 'from-blue-500 to-cyan-600 shadow-blue-200';
        if (n.includes('rebecca')) return 'from-amber-400 to-orange-500 shadow-orange-200';
        return 'from-gray-500 to-gray-700';
    };

    const balance = stats.salary.paid - stats.expenses.paid;

    if (!monthData) return <div className="flex items-center justify-center h-screen bg-gray-50"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-teal-600"></div></div>;

    const getTabStyle = (type: TransactionType) => {
        if (transactionListType !== type) return 'text-gray-400 hover:text-gray-600 hover:bg-gray-50';

        switch(type) {
            case 'incomes': return 'bg-emerald-50 text-emerald-700 shadow-sm';
            case 'expenses': return 'bg-rose-50 text-rose-700 shadow-sm';
            case 'avulsosItems': return 'bg-amber-50 text-amber-700 shadow-sm';
            default: return 'bg-teal-50 text-teal-700 shadow-sm';
        }
    };

    return (
        <div className="flex flex-col h-screen w-full bg-gray-50">
            <Header 
                month={currentMonth} 
                year={currentYear} 
                balance={balance}
                onMonthChange={handleMonthChange}
                onToggleSidebar={() => setSidebarOpen(true)}
                onOpenAi={() => setAiOpen(true)}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
                syncStatus={syncStatus}
            />

            <Sidebar 
                isOpen={sidebarOpen} 
                onClose={() => setSidebarOpen(false)} 
                accounts={monthData.bankAccounts}
                syncStatus={syncStatus}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
                currentView={view}
                onNavigate={setView}
            />

            <AiChat 
                isOpen={aiOpen} 
                onClose={() => setAiOpen(false)} 
                currentMonthData={monthData}
                projections={projections}
                initialMessage={aiInitialMessage}
            />

            {/* Adjusted padding bottom since nav bar is gone */}
            <main className="flex-1 overflow-y-auto p-4 pb-6 scroll-smooth">
                {view === 'home' && (
                    <div className="flex flex-col gap-6 animate-fadeIn">
                        {/* Grid de Resumo */}
                        <div className="flex flex-col gap-3">
                            <div className="grid grid-cols-2 gap-3">
                                <SummaryCard 
                                    title="Entradas (Salário)"
                                    value={stats.salary.total}
                                    type="success"
                                    progress={{ value: stats.salary.paid, max: stats.salary.total || 1 }}
                                    compact={true}
                                />
                                <SummaryCard 
                                    title="Entradas (Sal. + Mumbuca)"
                                    subtitle="-8% taxa de troca"
                                    value={stats.combined.total}
                                    type="info"
                                    progress={{ value: stats.combined.paid, max: stats.combined.total || 1 }}
                                    compact={true}
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <SummaryCard 
                                    title="Despesas Totais"
                                    value={stats.expenses.total}
                                    type="danger"
                                    progress={{ value: stats.expenses.paid, max: stats.expenses.total || 1 }}
                                    compact={true}
                                />
                                <SummaryCard 
                                    title="Sobras (Previsto)"
                                    value={stats.surplusRaw}
                                    type="final"
                                    subtitle="Antes da distribuição"
                                    compact={true}
                                />
                            </div>
                        </div>

                        {/* PERSONAL DEBTS CARDS (GROUPED) */}
                        {groupedDebts.length > 0 && (
                            <div className="flex flex-col gap-2">
                                <h3 className="text-base font-extrabold text-gray-800 px-1">Compromissos Pessoais</h3>
                                <div className="grid grid-cols-2 gap-3">
                                    {groupedDebts.map(group => {
                                        const colorClass = getDebtColor(group.name);
                                        const isFullyPaid = group.paidAmount >= group.total && group.total > 0;
                                        const percentage = (group.paidAmount / (group.total || 1)) * 100;

                                        return (
                                            <div 
                                                key={group.name} 
                                                onClick={() => handleToggleGroupPaid(group.items)}
                                                className={`relative overflow-hidden rounded-2xl p-4 bg-gradient-to-br ${colorClass} text-white shadow-lg active:scale-95 transition-all cursor-pointer`}
                                            >
                                                {/* Background pattern */}
                                                <div className="absolute top-0 right-0 p-2 opacity-20">
                                                    <User size={40} />
                                                </div>

                                                <div className="flex flex-col gap-1 relative z-10">
                                                    <div className="flex justify-between items-start">
                                                        <span className="text-xs font-bold uppercase tracking-wider opacity-90">{group.name}</span>
                                                        {isFullyPaid && <div className="bg-white/30 rounded-full p-0.5"><div className="w-1.5 h-1.5 bg-white rounded-full"></div></div>}
                                                    </div>

                                                    <span className={`text-2xl font-black tracking-tight ${isFullyPaid ? 'line-through opacity-70' : ''}`}>
                                                        {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(group.total)}
                                                    </span>

                                                    {/* Progress Bar for the group */}
                                                    <div className="mt-2 w-full bg-black/20 rounded-full h-1.5 overflow-hidden flex">
                                                        <div 
                                                            className="h-full bg-white/90 rounded-full transition-all duration-500" 
                                                            style={{ width: `${percentage}%` }}
                                                        ></div>
                                                    </div>

                                                    <div className="flex justify-between items-center mt-1 opacity-80">
                                                        <span className="text-[10px] font-bold">
                                                            {group.items.length} {group.items.length === 1 ? 'item' : 'itens'}
                                                        </span>
                                                        <span className="text-[10px] font-bold">
                                                            {Math.round(percentage)}% pago
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {view === 'transactions' && (
                    <div className="flex flex-col gap-4 animate-fadeIn">
                        <div className="sticky top-0 z-20 bg-gray-50 pb-2">
                            <div className="flex p-1 bg-white border border-gray-200 rounded-xl shadow-sm">
                                {(['incomes', 'expenses', 'avulsosItems'] as const).map(type => (
                                    <button
                                        key={type}
                                        onClick={() => setTransactionListType(type)}
                                        className={`flex-1 py-3 px-2 rounded-lg text-sm font-extrabold uppercase tracking-wide transition-all ${getTabStyle(type)}`}
                                    >
                                        {type === 'incomes' ? 'Entradas' : 
                                         type === 'expenses' ? 'Despesas' :
                                         'Avulsos'}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <TransactionList 
                            transactions={monthData[transactionListType]}
                            onTogglePaid={(id, paid) => handleTogglePaid(id, paid, transactionListType)}
                            onEdit={(item) => console.log("Edit", item)}
                        />
                    </div>
                )}

                {view === 'goals' && (
                    <div className="flex flex-col animate-fadeIn gap-4">
                        <div className="bg-gradient-to-br from-indigo-600 to-indigo-700 rounded-3xl p-6 text-white shadow-lg shadow-indigo-600/20">
                            <div className="flex items-center gap-3 mb-2">
                                <div className="p-2 bg-white/20 rounded-xl">
                                    <Target size={24} />
                                </div>
                                <h3 className="text-xl font-black">Distribuição de Sobras</h3>
                            </div>
                            <p className="text-indigo-50 text-sm font-medium leading-relaxed">
                                Acompanhe quanto você já separou para cada objetivo este mês. Marque como "Pago" no extrato para encher as barras.
                            </p>
                        </div>

                        {monthData.goals.length === 0 ? (
                            <div className="text-center py-10 text-gray-400 font-medium">
                                Nenhuma meta de distribuição configurada para este mês.
                                {currentYear === 2026 && currentMonth < 3 && <span className="block text-xs mt-1">(Disponível a partir de Março/2026)</span>}
                            </div>
                        ) : (
                            <div className="flex flex-col gap-3">
                                {monthData.goals.map(goal => {
                                    // Find Linked Transaction to see if it is paid
                                    const linkedTransaction = monthData.expenses.find(t => t.id === goal.linkedTransactionId);
                                    const isPaid = linkedTransaction?.paid || false;
                                    const currentAmount = isPaid ? goal.amount : 0;
                                    const percentage = (currentAmount / goal.amount) * 100;

                                    // Visual Config based on Category
                                    const getConfig = (cat: string) => {
                                        if (cat.includes('Lazer') || goal.name?.includes('Viagem')) return { bg: 'bg-sky-50', border: 'border-sky-100', text: 'text-sky-900', bar: 'bg-sky-500', icon: Plane };
                                        if (cat.includes('Investimento')) return { bg: 'bg-emerald-50', border: 'border-emerald-100', text: 'text-emerald-900', bar: 'bg-emerald-500', icon: PiggyBank };
                                        if (cat.includes('Alimentação') || goal.name?.includes('Casa')) return { bg: 'bg-amber-50', border: 'border-amber-100', text: 'text-amber-900', bar: 'bg-amber-500', icon: ShoppingBag };
                                        return { bg: 'bg-purple-50', border: 'border-purple-100', text: 'text-purple-900', bar: 'bg-purple-500', icon: Wallet };
                                    };

                                    const s = getConfig(goal.category);
                                    const Icon = s.icon;

                                    return (
                                        <div key={goal.id} className={`p-5 rounded-2xl border ${s.border} ${s.bg} shadow-sm flex flex-col gap-4 transition-all`}>
                                            <div className="flex justify-between items-start">
                                                <div className="flex items-center gap-3">
                                                    <div className={`w-10 h-10 rounded-full bg-white flex items-center justify-center ${s.text} shadow-sm`}>
                                                        <Icon size={20} strokeWidth={2.5} />
                                                    </div>
                                                    <div className="flex flex-col">
                                                        <span className={`font-bold text-sm ${s.text}`}>{goal.name}</span>
                                                        <span className="text-xs font-bold opacity-60 uppercase">{isPaid ? 'Valor em Caixa' : 'Aguardando Depósito'}</span>
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="flex flex-col gap-1">
                                                <div className="flex justify-between items-end mb-1">
                                                    <span className={`text-2xl font-black ${s.text}`}>
                                                        {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(currentAmount)}
                                                    </span>
                                                    <span className={`text-xs font-bold ${s.text} opacity-70`}>
                                                        Meta: {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(goal.amount)}
                                                    </span>
                                                </div>
                                                <div className="h-3 w-full bg-white rounded-full overflow-hidden shadow-inner">
                                                    <div className={`h-full rounded-full transition-all duration-500 ${s.bar}`} style={{ width: `${percentage}%` }}></div>
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                )}
            </main>

            {/* Floating Action Button - Adjusted Position since Nav is gone */}
            <button className="fixed bottom-6 right-5 w-16 h-16 bg-gray-900 text-white rounded-full shadow-[0_8px_30px_rgb(0,0,0,0.3)] flex items-center justify-center hover:scale-105 active:scale-95 transition-all z-30">
                <Plus size={32} strokeWidth={3} />
            </button>
        </div>
    );
};

export default App;

import React, { useEffect, useState, useMemo } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import SummaryCard from './components/SummaryCard';
import TransactionList from './components/TransactionList';
import AiChat from './components/AiChat';
import { MonthData, TransactionType, Transaction, FinancialProjection } from './types';
import { generateMonthData, getStorageKey } from './utils/financeUtils';
import { db, auth, isConfigured, onAuthStateChanged, signInAnonymously } from './services/firebaseConfig';
import { doc, getDoc, setDoc, onSnapshot } from 'firebase/firestore';
import { FAMILY_ID } from './constants';
import { Target, Plus, ShoppingBag, User, Plane, Wallet, PiggyBank, Home as HomeIcon } from 'lucide-react';

const App: React.FC = () => {
    // App State
    const [currentMonth, setCurrentMonth] = useState(2); // Inicia em Fevereiro
    const [currentYear, setCurrentYear] = useState(2026);
    const [monthData, setMonthData] = useState<MonthData | null>(null);
    const [view, setView] = useState<'home' | 'transactions' | 'goals'>('home');
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [aiOpen, setAiOpen] = useState(false);
    const [syncStatus, setSyncStatus] = useState<'offline' | 'syncing' | 'online'>('offline');
    const [transactionListType, setTransactionListType] = useState<TransactionType>('expenses');

    // Added state for pre-filling AI message
    const [aiInitialMessage, setAiInitialMessage] = useState<string>('');

    // Load Initial Data
    useEffect(() => {
        loadData(currentYear, currentMonth);

        // Auth Setup
        if (isConfigured && auth) {
            onAuthStateChanged(auth, (user) => {
                if (user) {
                    setSyncStatus('online');
                    setupRealtimeListener(currentYear, currentMonth);
                } else {
                    signInAnonymously(auth).catch((e) => {
                        // Handle specific API not enabled error gracefully
                        if (e.message && e.message.includes('identity-toolkit-api-has-not-been-used')) {
                            console.warn("Firebase Auth API not enabled. Running in Offline Mode.");
                        } else {
                            console.error("Auth Error", e);
                        }
                        setSyncStatus('offline');
                    });
                }
            });
        }
    }, []);

    const loadData = async (year: number, month: number) => {
        const key = getStorageKey(year, month);
        const local = localStorage.getItem(key);
        if (local) {
            setMonthData(JSON.parse(local));
        } else {
            const newData = generateMonthData(year, month);
            setMonthData(newData);
            saveData(newData, year, month);
        }
    };

    const saveData = async (data: MonthData, year: number, month: number) => {
        const key = getStorageKey(year, month);
        localStorage.setItem(key, JSON.stringify(data));
        setMonthData({ ...data }); // Force update

        if (syncStatus === 'online' && isConfigured) {
            setSyncStatus('syncing');
            try {
                const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
                await setDoc(docRef, data);
                setSyncStatus('online');
            } catch (e) {
                console.error("Sync failed", e);
                setSyncStatus('offline');
            }
        }
    };

    const setupRealtimeListener = (year: number, month: number) => {
        if (!isConfigured) return;
        const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
        return onSnapshot(docRef, (snap) => {
            if (snap.exists()) {
                const cloudData = snap.data() as MonthData;
                const localKey = getStorageKey(year, month);
                const localStr = localStorage.getItem(localKey);

                // Simple conflict resolution: Cloud wins if newer or local is missing
                if (!localStr || cloudData.updatedAt > JSON.parse(localStr).updatedAt) {
                    setMonthData(cloudData);
                    localStorage.setItem(localKey, JSON.stringify(cloudData));
                }
            }
        });
    };

    const handleMonthChange = (diff: number) => {
        let newMonth = currentMonth + diff;
        let newYear = currentYear;
        if (newMonth > 12) { newMonth = 1; newYear++; }
        if (newMonth < 1) { newMonth = 12; newYear--; }
        setCurrentMonth(newMonth);
        setCurrentYear(newYear);
        loadData(newYear, newMonth);
    };

    const handleTogglePaid = (id: string, paid: boolean, type: TransactionType) => {
        if (!monthData) return;
        const newData = { ...monthData };
        const item = newData[type].find(t => t.id === id);
        if (item) {
            item.paid = paid;
            item.updatedAt = Date.now(); // Internal flag not in interface but useful
            saveData(newData, currentYear, currentMonth);
        }
    };

    const handleToggleGroupPaid = (items: Transaction[]) => {
        if (!monthData) return;
        // Check if all are currently paid to decide whether to uncheck or check all
        const allPaid = items.every(i => i.paid);
        const newStatus = !allPaid;

        const newData = { ...monthData };
        items.forEach(groupItem => {
            const target = newData.expenses.find(e => e.id === groupItem.id);
            if (target) {
                target.paid = newStatus;
            }
        });
        newData.updatedAt = Date.now();
        saveData(newData, currentYear, currentMonth);
    };

    // Open AI with specific context
    const openAiWithContext = (message: string) => {
        setAiInitialMessage(message);
        setAiOpen(true);
    };

    // --- Calculations ---
    const stats = useMemo(() => {
        if (!monthData) return { 
            salary: { total: 0, paid: 0 }, 
            realExpenses: { total: 0, paid: 0 },
            distribution: { total: 0, paid: 0 },
            mumbuca: { total: 0, paid: 0, expenses: 0, expensesPaid: 0 },
            combined: { total: 0, paid: 0 },
            surplusRaw: 0
        };

        const calc = (items: Transaction[], paidOnly = false) => 
            items.filter(i => paidOnly ? i.paid : true).reduce((sum, i) => sum + i.amount, 0);

        // Split expenses into Real vs Distribution
        const realExpensesList = monthData.expenses.filter(e => !e.isDistribution);
        const distributionList = monthData.expenses.filter(e => e.isDistribution);

        // Salary Logic: Category 'Salário', 'Doação', 'Renda Extra'
        const salaryItems = monthData.incomes.filter(i => ['Salário', 'Doação', 'Renda Extra'].includes(i.category));

        // Mumbuca Logic
        const mumbucaItems = monthData.incomes.filter(i => i.category === 'Mumbuca');

        const salaryTotal = calc(salaryItems);
        const salaryPaid = calc(salaryItems, true);

        const mumbucaTotalRaw = calc(mumbucaItems);
        const mumbucaPaidRaw = calc(mumbucaItems, true);

        // Mumbuca Net (Minus 8% fee)
        const mumbucaNetTotal = mumbucaTotalRaw * 0.92;
        const mumbucaNetPaid = mumbucaPaidRaw * 0.92;

        const combinedTotal = salaryTotal + mumbucaNetTotal;

        // Stats for Real Expenses (excluding allocation/distribution)
        const realExpensesTotal = calc(realExpensesList);
        const realExpensesPaid = calc(realExpensesList, true);

        // Stats for Distribution
        const distributionTotal = calc(distributionList);
        const distributionPaid = calc(distributionList, true);

        return {
            salary: {
                total: salaryTotal,
                paid: salaryPaid
            },
            realExpenses: {
                total: realExpensesTotal,
                paid: realExpensesPaid
            },
            distribution: {
                total: distributionTotal,
                paid: distributionPaid
            },
            mumbuca: {
                total: mumbucaTotalRaw,
                paid: mumbucaPaidRaw,
                expenses: calc(monthData.shoppingItems),
                expensesPaid: calc(monthData.shoppingItems, true)
            },
            combined: {
                total: combinedTotal,
                paid: salaryPaid + mumbucaNetPaid
            },
            surplusRaw: combinedTotal - realExpensesTotal
        };
    }, [monthData]);

    // Financial Projections Logic (Simplified for brevity)
    const projections: FinancialProjection[] = useMemo(() => {
        if(!monthData) return [];
        return [{
            month: 'Atual',
            year: currentYear,
            fixedIncome: stats.salary.total,
            recurringExpenses: monthData.expenses.filter(e => !e.installments && !e.isDistribution).reduce((s, e) => s + e.amount, 0),
            committedInstallments: monthData.expenses.filter(e => e.installments && !e.isDistribution).reduce((s, e) => s + e.amount, 0),
            totalCommitted: stats.realExpenses.total,
            margin: stats.salary.total - stats.realExpenses.total,
            details: monthData.expenses.filter(e => !e.isDistribution).map(e => `${e.description}: ${e.amount}`)
        }];
    }, [monthData, stats, currentYear]);

    // Group Personal Debts
    const groupedDebts = useMemo(() => {
        if (!monthData) return [];
        const targets = ['Lili Torres', 'Marcia Brito', 'Marcia Bispo', 'Rebecca Brito'];

        // Map to store groups
        const groups: Record<string, { 
            name: string, 
            total: number, 
            paidAmount: number, 
            items: Transaction[] 
        }> = {};

        monthData.expenses.forEach(e => {
            // Find if this expense belongs to a target person
            const personName = targets.find(t => e.description.toLowerCase().includes(t.toLowerCase()));

            if (personName) {
                if (!groups[personName]) {
                    groups[personName] = { 
                        name: personName, 
                        total: 0, 
                        paidAmount: 0, 
                        items: [] 
                    };
                }
                groups[personName].items.push(e);
                groups[personName].total += e.amount;
                if (e.paid) {
                    groups[personName].paidAmount += e.amount;
                }
            }
        });

        return Object.values(groups);
    }, [monthData]);

    const getDebtColor = (name: string) => {
        const n = name.toLowerCase();
        if (n.includes('lili')) return 'from-pink-500 to-rose-600 shadow-pink-200';
        if (n.includes('marcia brito')) return 'from-violet-500 to-purple-600 shadow-violet-200';
        if (n.includes('marcia bispo')) return 'from-blue-500 to-cyan-600 shadow-blue-200';
        if (n.includes('rebecca')) return 'from-amber-400 to-orange-500 shadow-orange-200';
        return 'from-gray-500 to-gray-700';
    };

    // Correct Balance: Income Paid - Real Expenses Paid (Ignoring distribution items)
    const balance = stats.salary.paid - stats.realExpenses.paid;

    if (!monthData) return <div className="flex items-center justify-center h-screen bg-gray-50"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-teal-600"></div></div>;

    const getTabStyle = (type: TransactionType) => {
        if (transactionListType !== type) return 'text-gray-400 hover:text-gray-600 hover:bg-gray-50';

        switch(type) {
            case 'incomes': return 'bg-emerald-50 text-emerald-700 shadow-sm';
            case 'expenses': return 'bg-rose-50 text-rose-700 shadow-sm';
            case 'avulsosItems': return 'bg-amber-50 text-amber-700 shadow-sm';
            default: return 'bg-teal-50 text-teal-700 shadow-sm';
        }
    };

    return (
        <div className="flex flex-col h-screen w-full bg-gray-50">
            <Header 
                month={currentMonth} 
                year={currentYear} 
                balance={balance}
                onMonthChange={handleMonthChange}
                onToggleSidebar={() => setSidebarOpen(true)}
                onOpenAi={() => setAiOpen(true)}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
                syncStatus={syncStatus}
            />

            <Sidebar 
                isOpen={sidebarOpen} 
                onClose={() => setSidebarOpen(false)} 
                accounts={monthData.bankAccounts}
                syncStatus={syncStatus}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
                currentView={view}
                onNavigate={setView}
            />

            <AiChat 
                isOpen={aiOpen} 
                onClose={() => setAiOpen(false)} 
                currentMonthData={monthData}
                projections={projections}
                initialMessage={aiInitialMessage}
            />

            {/* Adjusted padding bottom since nav bar is gone */}
            <main className="flex-1 overflow-y-auto p-4 pb-6 scroll-smooth">
                {view === 'home' && (
                    <div className="flex flex-col gap-6 animate-fadeIn">
                        {/* Grid de Resumo */}
                        <div className="flex flex-col gap-3">
                            <div className="grid grid-cols-2 gap-3">
                                <SummaryCard 
                                    title="Entradas (Salário)"
                                    value={stats.salary.total}
                                    type="success"
                                    progress={{ value: stats.salary.paid, max: stats.salary.total || 1 }}
                                    compact={true}
                                />
                                <SummaryCard 
                                    title="Entradas (Sal. + Mumbuca)"
                                    subtitle="-8% taxa de troca"
                                    value={stats.combined.total}
                                    type="info"
                                    progress={{ value: stats.combined.paid, max: stats.combined.total || 1 }}
                                    compact={true}
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <SummaryCard 
                                    title="Despesas Totais"
                                    value={stats.realExpenses.total}
                                    type="danger"
                                    progress={{ value: stats.realExpenses.paid, max: stats.realExpenses.total || 1 }}
                                    compact={true}
                                />
                                <SummaryCard 
                                    title="Sobras (Previsto)"
                                    // Shows Total Surplus minus what was already allocated/paid
                                    value={stats.surplusRaw - stats.distribution.paid}
                                    type="final"
                                    subtitle="Restante para distribuir"
                                    compact={true}
                                />
                            </div>
                        </div>

                        {/* PERSONAL DEBTS CARDS (GROUPED) */}
                        {groupedDebts.length > 0 && (
                            <div className="flex flex-col gap-2">
                                <h3 className="text-base font-extrabold text-gray-800 px-1">Compromissos Pessoais</h3>
                                <div className="grid grid-cols-2 gap-3">
                                    {groupedDebts.map(group => {
                                        const colorClass = getDebtColor(group.name);
                                        const isFullyPaid = group.paidAmount >= group.total && group.total > 0;
                                        const percentage = (group.paidAmount / (group.total || 1)) * 100;

                                        return (
                                            <div 
                                                key={group.name} 
                                                onClick={() => handleToggleGroupPaid(group.items)}
                                                className={`relative overflow-hidden rounded-2xl p-4 bg-gradient-to-br ${colorClass} text-white shadow-lg active:scale-95 transition-all cursor-pointer`}
                                            >
                                                {/* Background pattern */}
                                                <div className="absolute top-0 right-0 p-2 opacity-20">
                                                    <User size={40} />
                                                </div>

                                                <div className="flex flex-col gap-1 relative z-10">
                                                    <div className="flex justify-between items-start">
                                                        <span className="text-xs font-bold uppercase tracking-wider opacity-90">{group.name}</span>
                                                        {isFullyPaid && <div className="bg-white/30 rounded-full p-0.5"><div className="w-1.5 h-1.5 bg-white rounded-full"></div></div>}
                                                    </div>

                                                    <span className={`text-2xl font-black tracking-tight ${isFullyPaid ? 'line-through opacity-70' : ''}`}>
                                                        {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(group.total)}
                                                    </span>

                                                    {/* Progress Bar for the group */}
                                                    <div className="mt-2 w-full bg-black/20 rounded-full h-1.5 overflow-hidden flex">
                                                        <div 
                                                            className="h-full bg-white/90 rounded-full transition-all duration-500" 
                                                            style={{ width: `${percentage}%` }}
                                                        ></div>
                                                    </div>

                                                    <div className="flex justify-between items-center mt-1 opacity-80">
                                                        <span className="text-[10px] font-bold">
                                                            {group.items.length} {group.items.length === 1 ? 'item' : 'itens'}
                                                        </span>
                                                        <span className="text-[10px] font-bold">
                                                            {Math.round(percentage)}% pago
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {view === 'transactions' && (
                    <div className="flex flex-col gap-4 animate-fadeIn">
                        <div className="sticky top-0 z-20 bg-gray-50 pb-2">
                            <div className="flex p-1 bg-white border border-gray-200 rounded-xl shadow-sm">
                                {(['incomes', 'expenses', 'avulsosItems'] as const).map(type => (
                                    <button
                                        key={type}
                                        onClick={() => setTransactionListType(type)}
                                        className={`flex-1 py-3 px-2 rounded-lg text-sm font-extrabold uppercase tracking-wide transition-all ${getTabStyle(type)}`}
                                    >
                                        {type === 'incomes' ? 'Entradas' : 
                                         type === 'expenses' ? 'Despesas' :
                                         'Avulsos'}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <TransactionList 
                            transactions={monthData[transactionListType]}
                            onTogglePaid={(id, paid) => handleTogglePaid(id, paid, transactionListType)}
                            onEdit={(item) => console.log("Edit", item)}
                        />
                    </div>
                )}

                {view === 'goals' && (
                    <div className="flex flex-col animate-fadeIn gap-4">
                        <div className="bg-gradient-to-br from-indigo-600 to-indigo-700 rounded-3xl p-6 text-white shadow-lg shadow-indigo-600/20">
                            <div className="flex items-center gap-3 mb-2">
                                <div className="p-2 bg-white/20 rounded-xl">
                                    <Target size={24} />
                                </div>
                                <h3 className="text-xl font-black">Distribuição de Sobras</h3>
                            </div>
                            <p className="text-indigo-50 text-sm font-medium leading-relaxed">
                                Acompanhe quanto você já separou para cada objetivo este mês. Marque como "Pago" no extrato para encher as barras.
                            </p>
                        </div>

                        {monthData.goals.length === 0 ? (
                            <div className="text-center py-10 text-gray-400 font-medium">
                                Nenhuma meta de distribuição configurada para este mês.
                                {currentYear === 2026 && currentMonth < 3 && <span className="block text-xs mt-1">(Disponível a partir de Março/2026)</span>}
                            </div>
                        ) : (
                            <div className="flex flex-col gap-3">
                                {monthData.goals.map(goal => {
                                    // Find Linked Transaction to see if it is paid
                                    const linkedTransaction = monthData.expenses.find(t => t.id === goal.linkedTransactionId);
                                    const isPaid = linkedTransaction?.paid || false;
                                    const currentAmount = isPaid ? goal.amount : 0;
                                    const percentage = (currentAmount / goal.amount) * 100;

                                    // Visual Config based on Category
                                    const getConfig = (cat: string) => {
                                        if (cat.includes('Lazer') || goal.name?.includes('Viagem')) return { bg: 'bg-sky-50', border: 'border-sky-100', text: 'text-sky-900', bar: 'bg-sky-500', icon: Plane };
                                        if (cat.includes('Investimento')) return { bg: 'bg-emerald-50', border: 'border-emerald-100', text: 'text-emerald-900', bar: 'bg-emerald-500', icon: PiggyBank };
                                        if (cat.includes('Alimentação') || goal.name?.includes('Casa')) return { bg: 'bg-amber-50', border: 'border-amber-100', text: 'text-amber-900', bar: 'bg-amber-500', icon: ShoppingBag };
                                        return { bg: 'bg-purple-50', border: 'border-purple-100', text: 'text-purple-900', bar: 'bg-purple-500', icon: Wallet };
                                    };

                                    const s = getConfig(goal.category);
                                    const Icon = s.icon;

                                    return (
                                        <div key={goal.id} className={`p-5 rounded-2xl border ${s.border} ${s.bg} shadow-sm flex flex-col gap-4 transition-all`}>
                                            <div className="flex justify-between items-start">
                                                <div className="flex items-center gap-3">
                                                    <div className={`w-10 h-10 rounded-full bg-white flex items-center justify-center ${s.text} shadow-sm`}>
                                                        <Icon size={20} strokeWidth={2.5} />
                                                    </div>
                                                    <div className="flex flex-col">
                                                        <span className={`font-bold text-sm ${s.text}`}>{goal.name}</span>
                                                        <span className="text-xs font-bold opacity-60 uppercase">{isPaid ? 'Valor em Caixa' : 'Aguardando Depósito'}</span>
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="flex flex-col gap-1">
                                                <div className="flex justify-between items-end mb-1">
                                                    <span className={`text-2xl font-black ${s.text}`}>
                                                        {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(currentAmount)}
                                                    </span>
                                                    <span className={`text-xs font-bold ${s.text} opacity-70`}>
                                                        Meta: {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(goal.amount)}
                                                    </span>
                                                </div>
                                                <div className="h-3 w-full bg-white rounded-full overflow-hidden shadow-inner">
                                                    <div className={`h-full rounded-full transition-all duration-500 ${s.bar}`} style={{ width: `${percentage}%` }}></div>
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                )}
            </main>

            {/* Floating Action Button - Adjusted Position since Nav is gone */}
            <button className="fixed bottom-6 right-5 w-16 h-16 bg-gray-900 text-white rounded-full shadow-[0_8px_30px_rgb(0,0,0,0.3)] flex items-center justify-center hover:scale-105 active:scale-95 transition-all z-30">
                <Plus size={32} strokeWidth={3} />
            </button>
        </div>
    );
};

export default App;

import React, { useEffect, useState, useMemo } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import SummaryCard from './components/SummaryCard';
import TransactionList from './components/TransactionList';
import AiChat from './components/AiChat';
import { MonthData, TransactionType, Transaction, FinancialProjection } from './types';
import { generateMonthData, getStorageKey } from './utils/financeUtils';
import { db, auth, isConfigured, onAuthStateChanged, signInAnonymously } from './services/firebaseConfig';
import { doc, getDoc, setDoc, onSnapshot } from 'firebase/firestore';
import { FAMILY_ID } from './constants';
import { Target, Plus, ShoppingBag, User, Plane, Wallet, PiggyBank, Home as HomeIcon } from 'lucide-react';

const App: React.FC = () => {
    // App State
    const [currentMonth, setCurrentMonth] = useState(2); // Inicia em Fevereiro
    const [currentYear, setCurrentYear] = useState(2026);
    const [monthData, setMonthData] = useState<MonthData | null>(null);
    const [view, setView] = useState<'home' | 'transactions' | 'goals'>('home');
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [aiOpen, setAiOpen] = useState(false);
    const [syncStatus, setSyncStatus] = useState<'offline' | 'syncing' | 'online'>('offline');
    const [transactionListType, setTransactionListType] = useState<TransactionType>('expenses');

    // Added state for pre-filling AI message
    const [aiInitialMessage, setAiInitialMessage] = useState<string>('');

    // Load Initial Data
    useEffect(() => {
        loadData(currentYear, currentMonth);

        // Auth Setup
        if (isConfigured && auth) {
            onAuthStateChanged(auth, (user) => {
                if (user) {
                    setSyncStatus('online');
                    setupRealtimeListener(currentYear, currentMonth);
                } else {
                    signInAnonymously(auth).catch((e) => {
                        // Handle specific API not enabled error gracefully
                        if (e.message && e.message.includes('identity-toolkit-api-has-not-been-used')) {
                            console.warn("Firebase Auth API not enabled. Running in Offline Mode.");
                        } else {
                            console.error("Auth Error", e);
                        }
                        setSyncStatus('offline');
                    });
                }
            });
        }
    }, []);

    const loadData = async (year: number, month: number) => {
        const key = getStorageKey(year, month);
        const local = localStorage.getItem(key);
        if (local) {
            setMonthData(JSON.parse(local));
        } else {
            const newData = generateMonthData(year, month);
            setMonthData(newData);
            saveData(newData, year, month);
        }
    };

    const saveData = async (data: MonthData, year: number, month: number) => {
        const key = getStorageKey(year, month);
        localStorage.setItem(key, JSON.stringify(data));
        setMonthData({ ...data }); // Force update

        if (syncStatus === 'online' && isConfigured) {
            setSyncStatus('syncing');
            try {
                const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
                await setDoc(docRef, data);
                setSyncStatus('online');
            } catch (e) {
                console.error("Sync failed", e);
                setSyncStatus('offline');
            }
        }
    };

    const setupRealtimeListener = (year: number, month: number) => {
        if (!isConfigured) return;
        const docRef = doc(db, 'families', FAMILY_ID, 'months', `${year}-${month.toString().padStart(2, '0')}`);
        return onSnapshot(docRef, (snap) => {
            if (snap.exists()) {
                const cloudData = snap.data() as MonthData;
                const localKey = getStorageKey(year, month);
                const localStr = localStorage.getItem(localKey);

                // Simple conflict resolution: Cloud wins if newer or local is missing
                if (!localStr || cloudData.updatedAt > JSON.parse(localStr).updatedAt) {
                    setMonthData(cloudData);
                    localStorage.setItem(localKey, JSON.stringify(cloudData));
                }
            }
        });
    };

    const handleMonthChange = (diff: number) => {
        let newMonth = currentMonth + diff;
        let newYear = currentYear;
        if (newMonth > 12) { newMonth = 1; newYear++; }
        if (newMonth < 1) { newMonth = 12; newYear--; }
        setCurrentMonth(newMonth);
        setCurrentYear(newYear);
        loadData(newYear, newMonth);
    };

    const handleTogglePaid = (id: string, paid: boolean, type: TransactionType) => {
        if (!monthData) return;
        const newData = { ...monthData };
        const item = newData[type].find(t => t.id === id);
        if (item) {
            item.paid = paid;
            item.updatedAt = Date.now(); // Internal flag not in interface but useful
            saveData(newData, currentYear, currentMonth);
        }
    };

    const handleToggleGroupPaid = (items: Transaction[]) => {
        if (!monthData) return;
        // Check if all are currently paid to decide whether to uncheck or check all
        const allPaid = items.every(i => i.paid);
        const newStatus = !allPaid;

        const newData = { ...monthData };
        items.forEach(groupItem => {
            const target = newData.expenses.find(e => e.id === groupItem.id);
            if (target) {
                target.paid = newStatus;
            }
        });
        newData.updatedAt = Date.now();
        saveData(newData, currentYear, currentMonth);
    };

    // Open AI with specific context
    const openAiWithContext = (message: string) => {
        setAiInitialMessage(message);
        setAiOpen(true);
    };

    // --- Calculations ---
    const stats = useMemo(() => {
        if (!monthData) return { 
            salary: { total: 0, paid: 0 }, 
            realExpenses: { total: 0, paid: 0 },
            distribution: { total: 0, paid: 0 },
            mumbuca: { total: 0, paid: 0, expenses: 0, expensesPaid: 0 },
            combined: { total: 0, paid: 0 },
            surplusRaw: 0
        };

        const calc = (items: Transaction[], paidOnly = false) => 
            items.filter(i => paidOnly ? i.paid : true).reduce((sum, i) => sum + i.amount, 0);

        // Split expenses into Real vs Distribution
        const realExpensesList = monthData.expenses.filter(e => !e.isDistribution);
        const distributionList = monthData.expenses.filter(e => e.isDistribution);

        // Salary Logic: Category 'Salário', 'Doação', 'Renda Extra'
        const salaryItems = monthData.incomes.filter(i => ['Salário', 'Doação', 'Renda Extra'].includes(i.category));

        // Mumbuca Logic
        const mumbucaItems = monthData.incomes.filter(i => i.category === 'Mumbuca');

        const salaryTotal = calc(salaryItems);
        const salaryPaid = calc(salaryItems, true);

        const mumbucaTotalRaw = calc(mumbucaItems);
        const mumbucaPaidRaw = calc(mumbucaItems, true);

        // Mumbuca Net (Minus 8% fee)
        const mumbucaNetTotal = mumbucaTotalRaw * 0.92;
        const mumbucaNetPaid = mumbucaPaidRaw * 0.92;

        const combinedTotal = salaryTotal + mumbucaNetTotal;

        // Stats for Real Expenses (excluding allocation/distribution)
        const realExpensesTotal = calc(realExpensesList);
        const realExpensesPaid = calc(realExpensesList, true);

        // Stats for Distribution
        const distributionTotal = calc(distributionList);
        const distributionPaid = calc(distributionList, true);

        return {
            salary: {
                total: salaryTotal,
                paid: salaryPaid
            },
            realExpenses: {
                total: realExpensesTotal,
                paid: realExpensesPaid
            },
            distribution: {
                total: distributionTotal,
                paid: distributionPaid
            },
            mumbuca: {
                total: mumbucaTotalRaw,
                paid: mumbucaPaidRaw,
                expenses: calc(monthData.shoppingItems),
                expensesPaid: calc(monthData.shoppingItems, true)
            },
            combined: {
                total: combinedTotal,
                paid: salaryPaid + mumbucaNetPaid
            },
            surplusRaw: combinedTotal - realExpensesTotal
        };
    }, [monthData]);

    // Financial Projections Logic
    const projections: FinancialProjection[] = useMemo(() => {
        if(!monthData) return [];
        return [{
            month: 'Atual',
            year: currentYear,
            fixedIncome: stats.salary.total,
            recurringExpenses: monthData.expenses.filter(e => !e.installments && !e.isDistribution).reduce((s, e) => s + e.amount, 0),
            committedInstallments: monthData.expenses.filter(e => e.installments && !e.isDistribution).reduce((s, e) => s + e.amount, 0),
            totalCommitted: stats.realExpenses.total,
            margin: stats.salary.total - stats.realExpenses.total,
            details: monthData.expenses.filter(e => !e.isDistribution).map(e => `${e.description}: ${e.amount}`)
        }];
    }, [monthData, stats, currentYear]);

    // Calculate Accounts for Sidebar dynamically
    const sidebarAccounts = useMemo(() => {
        return [
            { 
                id: 'acc_main', 
                name: 'Conta Principal', 
                balance: stats.salary.total // Junção dos Salários
            },
            { 
                id: 'acc_mum', 
                name: 'Mumbuca', 
                balance: stats.mumbuca.total * 0.92 // Junção dos Mumbucas com 8% de desconto
            }
        ];
    }, [stats]);

    // Group Personal Debts
    const groupedDebts = useMemo(() => {
        if (!monthData) return [];
        const targets = ['Lili Torres', 'Marcia Brito', 'Marcia Bispo', 'Rebecca Brito'];

        // Map to store groups
        const groups: Record<string, { 
            name: string, 
            total: number, 
            paidAmount: number, 
            items: Transaction[] 
        }> = {};

        monthData.expenses.forEach(e => {
            // Find if this expense belongs to a target person
            const personName = targets.find(t => e.description.toLowerCase().includes(t.toLowerCase()));

            if (personName) {
                if (!groups[personName]) {
                    groups[personName] = { 
                        name: personName, 
                        total: 0, 
                        paidAmount: 0, 
                        items: [] 
                    };
                }
                groups[personName].items.push(e);
                groups[personName].total += e.amount;
                if (e.paid) {
                    groups[personName].paidAmount += e.amount;
                }
            }
        });

        return Object.values(groups);
    }, [monthData]);

    const getDebtColor = (name: string) => {
        const n = name.toLowerCase();
        if (n.includes('lili')) return 'from-pink-500 to-rose-600 shadow-pink-200';
        if (n.includes('marcia brito')) return 'from-violet-500 to-purple-600 shadow-violet-200';
        if (n.includes('marcia bispo')) return 'from-blue-500 to-cyan-600 shadow-blue-200';
        if (n.includes('rebecca')) return 'from-amber-400 to-orange-500 shadow-orange-200';
        return 'from-gray-500 to-gray-700';
    };

    // Correct Balance for Header: Income Paid - Real Expenses Paid (Ignoring distribution items)
    const balance = stats.salary.paid - stats.realExpenses.paid;

    if (!monthData) return <div className="flex items-center justify-center h-screen bg-gray-50"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-teal-600"></div></div>;

    const getTabStyle = (type: TransactionType) => {
        if (transactionListType !== type) return 'text-gray-400 hover:text-gray-600 hover:bg-gray-50';

        switch(type) {
            case 'incomes': return 'bg-emerald-50 text-emerald-700 shadow-sm';
            case 'expenses': return 'bg-rose-50 text-rose-700 shadow-sm';
            case 'avulsosItems': return 'bg-amber-50 text-amber-700 shadow-sm';
            default: return 'bg-teal-50 text-teal-700 shadow-sm';
        }
    };

    return (
        <div className="flex flex-col h-screen w-full bg-gray-50">
            <Header 
                month={currentMonth} 
                year={currentYear} 
                balance={balance}
                onMonthChange={handleMonthChange}
                onToggleSidebar={() => setSidebarOpen(true)}
                onOpenAi={() => setAiOpen(true)}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
                syncStatus={syncStatus}
            />

            <Sidebar 
                isOpen={sidebarOpen} 
                onClose={() => setSidebarOpen(false)} 
                accounts={sidebarAccounts} // Pass dynamically calculated accounts
                syncStatus={syncStatus}
                onSync={() => saveData(monthData, currentYear, currentMonth)}
                currentView={view}
                onNavigate={setView}
            />

            <AiChat 
                isOpen={aiOpen} 
                onClose={() => setAiOpen(false)} 
                currentMonthData={monthData}
                projections={projections}
                initialMessage={aiInitialMessage}
            />

            {/* Adjusted padding bottom since nav bar is gone */}
            <main className="flex-1 overflow-y-auto p-4 pb-6 scroll-smooth">
                {view === 'home' && (
                    <div className="flex flex-col gap-6 animate-fadeIn">
                        {/* Grid de Resumo */}
                        <div className="flex flex-col gap-3">
                            <div className="grid grid-cols-2 gap-3">
                                <SummaryCard 
                                    title="Entradas (Salário)"
                                    value={stats.salary.total}
                                    type="success"
                                    progress={{ value: stats.salary.paid, max: stats.salary.total || 1 }}
                                    compact={true}
                                />
                                <SummaryCard 
                                    title="Entradas (Sal. + Mumbuca)"
                                    subtitle="-8% taxa de troca"
                                    value={stats.combined.total}
                                    type="info"
                                    progress={{ value: stats.combined.paid, max: stats.combined.total || 1 }}
                                    compact={true}
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <SummaryCard 
                                    title="Despesas Totais"
                                    value={stats.realExpenses.total}
                                    type="danger"
                                    progress={{ value: stats.realExpenses.paid, max: stats.realExpenses.total || 1 }}
                                    compact={true}
                                />
                                <SummaryCard 
                                    title="Sobras (Previsto)"
                                    // Shows Total Surplus minus what was already allocated/paid
                                    value={stats.surplusRaw - stats.distribution.paid}
                                    type="final"
                                    subtitle="Restante para distribuir"
                                    compact={true}
                                />
                            </div>
                        </div>

                        {/* PERSONAL DEBTS CARDS (GROUPED) */}
                        {groupedDebts.length > 0 && (
                            <div className="flex flex-col gap-2">
                                <h3 className="text-base font-extrabold text-gray-800 px-1">Compromissos Pessoais</h3>
                                <div className="grid grid-cols-2 gap-3">
                                    {groupedDebts.map(group => {
                                        const colorClass = getDebtColor(group.name);
                                        const isFullyPaid = group.paidAmount >= group.total && group.total > 0;
                                        const percentage = (group.paidAmount / (group.total || 1)) * 100;

                                        return (
                                            <div 
                                                key={group.name} 
                                                onClick={() => handleToggleGroupPaid(group.items)}
                                                className={`relative overflow-hidden rounded-2xl p-4 bg-gradient-to-br ${colorClass} text-white shadow-lg active:scale-95 transition-all cursor-pointer`}
                                            >
                                                {/* Background pattern */}
                                                <div className="absolute top-0 right-0 p-2 opacity-20">
                                                    <User size={40} />
                                                </div>

                                                <div className="flex flex-col gap-1 relative z-10">
                                                    <div className="flex justify-between items-start">
                                                        <span className="text-xs font-bold uppercase tracking-wider opacity-90">{group.name}</span>
                                                        {isFullyPaid && <div className="bg-white/30 rounded-full p-0.5"><div className="w-1.5 h-1.5 bg-white rounded-full"></div></div>}
                                                    </div>

                                                    <span className={`text-2xl font-black tracking-tight ${isFullyPaid ? 'line-through opacity-70' : ''}`}>
                                                        {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(group.total)}
                                                    </span>

                                                    {/* Progress Bar for the group */}
                                                    <div className="mt-2 w-full bg-black/20 rounded-full h-1.5 overflow-hidden flex">
                                                        <div 
                                                            className="h-full bg-white/90 rounded-full transition-all duration-500" 
                                                            style={{ width: `${percentage}%` }}
                                                        ></div>
                                                    </div>

                                                    <div className="flex justify-between items-center mt-1 opacity-80">
                                                        <span className="text-[10px] font-bold">
                                                            {group.items.length} {group.items.length === 1 ? 'item' : 'itens'}
                                                        </span>
                                                        <span className="text-[10px] font-bold">
                                                            {Math.round(percentage)}% pago
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {view === 'transactions' && (
                    <div className="flex flex-col gap-4 animate-fadeIn">
                        <div className="sticky top-0 z-20 bg-gray-50 pb-2">
                            <div className="flex p-1 bg-white border border-gray-200 rounded-xl shadow-sm">
                                {(['incomes', 'expenses', 'avulsosItems'] as const).map(type => (
                                    <button
                                        key={type}
                                        onClick={() => setTransactionListType(type)}
                                        className={`flex-1 py-3 px-2 rounded-lg text-sm font-extrabold uppercase tracking-wide transition-all ${getTabStyle(type)}`}
                                    >
                                        {type === 'incomes' ? 'Entradas' : 
                                         type === 'expenses' ? 'Despesas' :
                                         'Avulsos'}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <TransactionList 
                            transactions={monthData[transactionListType]}
                            onTogglePaid={(id, paid) => handleTogglePaid(id, paid, transactionListType)}
                            onEdit={(item) => console.log("Edit", item)}
                        />
                    </div>
                )}

                {view === 'goals' && (
                    <div className="flex flex-col animate-fadeIn gap-4">
                        <div className="bg-gradient-to-br from-indigo-600 to-indigo-700 rounded-3xl p-6 text-white shadow-lg shadow-indigo-600/20">
                            <div className="flex items-center gap-3 mb-2">
                                <div className="p-2 bg-white/20 rounded-xl">
                                    <Target size={24} />
                                </div>
                                <h3 className="text-xl font-black">Distribuição de Sobras</h3>
                            </div>
                            <p className="text-indigo-50 text-sm font-medium leading-relaxed">
                                Acompanhe quanto você já separou para cada objetivo este mês. Marque como "Pago" no extrato para encher as barras.
                            </p>
                        </div>

                        {monthData.goals.length === 0 ? (
                            <div className="text-center py-10 text-gray-400 font-medium">
                                Nenhuma meta de distribuição configurada para este mês.
                                {currentYear === 2026 && currentMonth < 3 && <span className="block text-xs mt-1">(Disponível a partir de Março/2026)</span>}
                            </div>
                        ) : (
                            <div className="flex flex-col gap-3">
                                {monthData.goals.map(goal => {
                                    // Find Linked Transaction to see if it is paid
                                    const linkedTransaction = monthData.expenses.find(t => t.id === goal.linkedTransactionId);
                                    const isPaid = linkedTransaction?.paid || false;
                                    const currentAmount = isPaid ? goal.amount : 0;
                                    const percentage = (currentAmount / goal.amount) * 100;

                                    // Visual Config based on Category
                                    const getConfig = (cat: string) => {
                                        if (cat.includes('Lazer') || goal.name?.includes('Viagem')) return { bg: 'bg-sky-50', border: 'border-sky-100', text: 'text-sky-900', bar: 'bg-sky-500', icon: Plane };
                                        if (cat.includes('Investimento')) return { bg: 'bg-emerald-50', border: 'border-emerald-100', text: 'text-emerald-900', bar: 'bg-emerald-500', icon: PiggyBank };
                                        if (cat.includes('Alimentação') || goal.name?.includes('Casa')) return { bg: 'bg-amber-50', border: 'border-amber-100', text: 'text-amber-900', bar: 'bg-amber-500', icon: ShoppingBag };
                                        return { bg: 'bg-purple-50', border: 'border-purple-100', text: 'text-purple-900', bar: 'bg-purple-500', icon: Wallet };
                                    };

                                    const s = getConfig(goal.category);
                                    const Icon = s.icon;

                                    return (
                                        <div key={goal.id} className={`p-5 rounded-2xl border ${s.border} ${s.bg} shadow-sm flex flex-col gap-4 transition-all`}>
                                            <div className="flex justify-between items-start">
                                                <div className="flex items-center gap-3">
                                                    <div className={`w-10 h-10 rounded-full bg-white flex items-center justify-center ${s.text} shadow-sm`}>
                                                        <Icon size={20} strokeWidth={2.5} />
                                                    </div>
                                                    <div className="flex flex-col">
                                                        <span className={`font-bold text-sm ${s.text}`}>{goal.name}</span>
                                                        <span className="text-xs font-bold opacity-60 uppercase">{isPaid ? 'Valor em Caixa' : 'Aguardando Depósito'}</span>
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="flex flex-col gap-1">
                                                <div className="flex justify-between items-end mb-1">
                                                    <span className={`text-2xl font-black ${s.text}`}>
                                                        {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(currentAmount)}
                                                    </span>
                                                    <span className={`text-xs font-bold ${s.text} opacity-70`}>
                                                        Meta: {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(goal.amount)}
                                                    </span>
                                                </div>
                                                <div className="h-3 w-full bg-white rounded-full overflow-hidden shadow-inner">
                                                    <div className={`h-full rounded-full transition-all duration-500 ${s.bar}`} style={{ width: `${percentage}%` }}></div>
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                )}
            </main>

            {/* Floating Action Button - Adjusted Position since Nav is gone */}
            <button className="fixed bottom-6 right-5 w-16 h-16 bg-gray-900 text-white rounded-full shadow-[0_8px_30px_rgb(0,0,0,0.3)] flex items-center justify-center hover:scale-105 active:scale-95 transition-all z-30">
                <Plus size={32} strokeWidth={3} />
            </button>
        </div>
    );
};

export default App;

