import React, { useState } from 'react';
import { ShieldCheck, ShieldAlert, TrendingUp, Zap, Activity, Info, X, ArrowRight } from 'lucide-react';

interface FinancialHealthWidgetProps {
    income: number;
    expenses: number;
    surplus: number;
}

const FinancialHealthWidget: React.FC<FinancialHealthWidgetProps> = ({ income, expenses, surplus }) => {
    const [showInfo, setShowInfo] = useState(false);

    // Formatter
    const format = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', notation: 'compact' }).format(v);

    // Evita divisão por zero
    const safeIncome = income || 1;

    // Taxa de Poupança (Savings Rate) do MÊS ATUAL
    const savingsRate = (surplus / safeIncome) * 100;

    // Algoritmo de Score (0 a 1000)
    // Princípio: Score base 500 (neutro).
    // Ganha pontos pela % que sobra (Eficiência).
    let score = 500;

    if (surplus >= 0) {
        // Se guardar 30% da renda, ganha ~500 pontos extras -> Score 1000
        score += Math.min(500, (savingsRate * 16.6)); 
    } else {
        // Prejuízo pune mais forte
        const lossRate = Math.abs(savingsRate);
        score -= Math.min(500, (lossRate * 20));
    }

    score = Math.round(Math.max(0, Math.min(1000, score)));

    // Determina Nível e Cor
    let status = { text: '', color: '', icon: Activity, gradient: '', desc: '' };
    if (score >= 850) {
        status = { text: 'EXCELÊNCIA', color: 'text-emerald-400', icon: Zap, gradient: 'from-emerald-400 to-teal-300', desc: 'Capacidade de aporte elite.' };
    } else if (score >= 700) {
        status = { text: 'ALTA SOLIDEZ', color: 'text-cyan-400', icon: ShieldCheck, gradient: 'from-cyan-400 to-blue-400', desc: 'Sobra mensal acima da média.' };
    } else if (score >= 500) {
        status = { text: 'EQUILÍBRIO', color: 'text-indigo-400', icon: TrendingUp, gradient: 'from-indigo-400 to-violet-400', desc: 'Contas pagas, margem segura.' };
    } else if (score >= 300) {
        status = { text: 'ATENÇÃO', color: 'text-amber-400', icon: Activity, gradient: 'from-amber-400 to-orange-400', desc: 'Margem baixa. Risco leve.' };
    } else {
        status = { text: 'RISCO CRÍTICO', color: 'text-rose-500', icon: ShieldAlert, gradient: 'from-rose-500 to-red-600', desc: 'Despesas superam ganhos.' };
    }

    const Icon = status.icon;

    // SVG Circle Calculations
    const radius = 56;
    const circumference = 2 * Math.PI * radius;
    const offset = circumference - ((score / 1000) * circumference);

    return (
        <div className="relative w-full h-[180px] bg-slate-900 rounded-[2rem] shadow-2xl shadow-slate-900/20 overflow-hidden group border border-slate-800 transition-all">
            {/* Ambient Background Glow */}
            <div className={`absolute top-0 right-0 w-64 h-64 bg-gradient-to-br ${status.gradient} opacity-10 blur-[80px] rounded-full transform translate-x-1/3 -translate-y-1/3 pointer-events-none`}></div>

            {/* TOGGLE BUTTON (INFO) */}
            <button 
                onClick={() => setShowInfo(!showInfo)}
                className="absolute top-4 right-4 z-30 p-2 rounded-full bg-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all backdrop-blur-md border border-white/5"
            >
                {showInfo ? <X size={16} /> : <Info size={16} />}
            </button>

            {/* CONTENT LAYER 1: MAIN VIEW */}
            <div className={`absolute inset-0 p-5 flex flex-row items-center justify-between gap-2 transition-transform duration-500 ease-in-out ${showInfo ? '-translate-x-full opacity-0' : 'translate-x-0 opacity-100'}`}>
                {/* Left Side: Text Info */}
                <div className="flex flex-col h-full justify-between flex-1 min-w-0 py-1">
                    <div>
                        <div className="flex items-center gap-2 mb-2">
                            <div className={`p-1.5 rounded-lg bg-white/5 border border-white/10 ${status.color}`}>
                                <Icon size={14} strokeWidth={3} />
                            </div>
                            <span className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-400 truncate">Performance Mensal</span>
                        </div>

                        <h3 className={`text-xl sm:text-2xl font-black italic tracking-tighter text-transparent bg-clip-text bg-gradient-to-r ${status.gradient} drop-shadow-sm truncate pr-4`}>
                            {status.text}
                        </h3>

                        <p className="text-[10px] sm:text-xs font-bold text-slate-400 leading-relaxed mt-1 max-w-[180px]">
                            {status.desc} <br/>
                            <span className="opacity-50 font-normal">Baseado na sobra deste mês.</span>
                        </p>
                    </div>

                    <div className="flex items-center gap-4 mt-2">
                         <div className="flex flex-col">
                            <span className="text-[8px] font-extrabold uppercase text-slate-500 tracking-wider">Entradas</span>
                            <span className="text-xs font-black text-emerald-400">{format(income)}</span>
                        </div>
                        <div className="h-4 w-px bg-white/10"></div>
                        <div className="flex flex-col">
                            <span className="text-[8px] font-extrabold uppercase text-slate-500 tracking-wider">Potencial</span>
                            <span className={`text-xs font-black ${surplus >= 0 ? 'text-white' : 'text-rose-400'}`}>
                                {format(surplus)}
                            </span>
                        </div>
                    </div>
                </div>

                {/* Right Side: Radial Chart */}
                <div className="relative w-28 h-28 flex items-center justify-center shrink-0 mr-8 sm:mr-4">
                    <svg className="w-full h-full transform -rotate-90" viewBox="0 0 128 128">
                        <circle cx="64" cy="64" r={radius} stroke="currentColor" strokeWidth="8" fill="transparent" className="text-slate-800" />
                        <circle cx="64" cy="64" r={radius} stroke="currentColor" strokeWidth="8" fill="transparent"
                            strokeDasharray={circumference} strokeDashoffset={offset} strokeLinecap="round"
                            className={`${status.color} transition-all duration-1000 ease-out`}
                            style={{ filter: 'drop-shadow(0 0 4px rgba(currentColor, 0.5))' }}
                        />
                    </svg>
                    <div className="absolute inset-0 flex flex-col items-center justify-center">
