                    </div>
                </div>
            </div>

            {/* CONTENT LAYER 2: EXPLANATION (OVERLAY) */}
            <div className={`absolute inset-0 bg-slate-900/95 backdrop-blur-xl p-6 flex flex-col justify-center transition-transform duration-500 ease-in-out ${showInfo ? 'translate-x-0 opacity-100' : 'translate-x-full opacity-0'} z-20`}>
                <h4 className="text-white font-black text-sm uppercase tracking-widest mb-3 flex items-center gap-2">
                    <Info size={14} className="text-cyan-400" /> Entenda o Cálculo
                </h4>

                <p className="text-xs text-slate-300 font-medium leading-relaxed mb-4">
                    Este score <strong>não mede riqueza acumulada</strong>, mas sim sua <span className="text-white font-bold">eficiência financeira neste mês</span>.
                </p>

                <div className="space-y-2 mb-2">
                    <div className="flex justify-between items-center text-xs border-b border-white/5 pb-1">
                        <span className="text-slate-500 font-bold uppercase">Sua Renda</span>
                        <span className="text-emerald-400 font-black">{format(income)}</span>
                    </div>
                    <div className="flex justify-between items-center text-xs border-b border-white/5 pb-1">
                        <span className="text-slate-500 font-bold uppercase">Seus Gastos</span>
                        <span className="text-rose-400 font-black">{format(expenses)}</span>
                    </div>
                    <div className="flex justify-between items-center text-xs pt-1">
